action.command:
cd /workspace && python3 - <<'EOF' > /tmp/contract_summary.txt
import json
d=json.load(open('contracts/openapi.contract.json'))
def fmt(s, ind=0):
    out=[]
    p='  '*ind
    if not isinstance(s,dict): return [p+repr(s)]
    t=s.get('type')
    parts=[]
    if t: parts.append(t)
    if 'format' in s: parts.append(s['format'])
    if 'enum' in s: parts.append('enum'+str(s['enum']))
    if 'required' in s and t=='object': pass
    line=p+','.join(parts) if parts else p+'obj'
    out=[line]
    req=set(s.get('required',[]))
    for k,v in s.get('properties',{}).items():
        star='*' if k in req else ''
        sub=fmt(v,ind+1)
        sub[0]=sub[0].lstrip()
        out.append(p+f'  {k}{star}: '+sub[0])
        out.extend(sub[1:])
    if 'items' in s:
        sub=fmt(s['items'],ind+1)
        out.append(p+'  items: '+sub[0].lstrip()); out.extend(sub[1:])
    if s.get('additionalProperties') is False: out.append(p+'  [no additional]')
    for c in ('oneOf','anyOf','allOf'):
        if c in s:
            out.append(p+f'  {c}:')
            for i,sub in enumerate(s[c]):
                out.append(p+f'    [{i}]')
                out.extend(fmt(sub,ind+3))
    return out
for path,ops in d['paths'].items():
    for m,o in ops.items():
        print('='*80)
        print(m.upper(), path, '->', o.get('operationId'))
        rb=o.get('requestBody',{}).get('content',{}).get('application/json',{}).get('schema')
        if rb:
            print('REQUEST:')
            print('\n'.join(fmt(rb)))
        for code,r in o.get('responses',{}).items():
            sch=r.get('content',{}).get('application/json',{}).get('schema')
            print(f'RESPONSE {code}:')
            if sch: print('\n'.join(fmt(sch)))
EOF
wc -l /tmp/contract_summary.txt

