package main

import (
	"crypto/sha256"
	"database/sql"
	"encoding/hex"
	"encoding/json"
	"math"
	"net/http"
	"time"

	"github.com/google/uuid"
)

type M = map[string]any

type apiErr struct {
	status int
	code   string
	msg    string
}

func errOf(status int, code, msg string) *apiErr {
	return &apiErr{status, code, msg}
}

func writeErr(w http.ResponseWriter, status int, code, msg string) {
	writeJSON(w, status, M{"error": msg, "code": code})
}

func writeAPIErr(w http.ResponseWriter, e *apiErr) {
	writeErr(w, e.status, e.code, e.msg)
}

func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	json.NewEncoder(w).Encode(v)
}

func writeData(w http.ResponseWriter, status int, v any) {
	writeJSON(w, status, M{"data": v})
}

func decodeBody(r *http.Request, dst any) *apiErr {
	dec := json.NewDecoder(r.Body)
	dec.DisallowUnknownFields()
	if err := dec.Decode(dst); err != nil {
		return errOf(400, "invalid_json", "request body is not valid JSON or contains unknown fields: "+err.Error())
	}
	return nil
}

func decodeRaw(r *http.Request) (map[string]json.RawMessage, []byte, *apiErr) {
	var raw map[string]json.RawMessage
	dec := json.NewDecoder(r.Body)
	if err := dec.Decode(&raw); err != nil {
		return nil, nil, errOf(400, "invalid_json", "request body is not valid JSON: "+err.Error())
	}
	b, _ := json.Marshal(raw)
	return raw, b, nil
}

func newUUID() string { return uuid.NewString() }

func hashStr(s string) string {
	h := sha256.Sum256([]byte(s))
	return hex.EncodeToString(h[:])
}

func parseTime(s string) (time.Time, bool) {
	t, err := time.Parse(time.RFC3339, s)
	if err != nil {
		return time.Time{}, false
	}
	return t, true
}

func fmtTime(t time.Time) string { return t.UTC().Format(time.RFC3339) }

func fmtTimePtr(t *time.Time) any {
	if t == nil {
		return nil
	}
	return fmtTime(*t)
}

func haversineKm(lat1, lng1, lat2, lng2 float64) float64 {
	const R = 6371.0
	dLat := (lat2 - lat1) * math.Pi / 180
	dLng := (lng2 - lng1) * math.Pi / 180
	a := math.Sin(dLat/2)*math.Sin(dLat/2) +
		math.Cos(lat1*math.Pi/180)*math.Cos(lat2*math.Pi/180)*math.Sin(dLng/2)*math.Sin(dLng/2)
	return 2 * R * math.Atan2(math.Sqrt(a), math.Sqrt(1-a))
}

var validRoles = map[string]bool{
	"administrator": true, "dispatcher": true, "requester": true,
	"collection_professional": true, "delivery_partner": true,
	"node_handler": true, "laboratory_team": true,
}

var validFunctions = map[string]bool{
	"collection_point": true, "transfer_point": true, "hub": true, "laboratory": true,
}

const staleLocationAfter = 5 * time.Minute

func isStale(recordedAt *time.Time) bool {
	if recordedAt == nil {
		return true
	}
	return time.Since(*recordedAt) > staleLocationAfter
}

func audit(actorID, role, action, entityType, entityID string, success bool, details M) {
	if details == nil {
		details = M{}
	}
	d, _ := json.Marshal(details)
	db.Exec(`INSERT INTO audit_log(audit_id,actor_id,role,action,entity_type,entity_id,success,details) VALUES($1,$2,$3,$4,$5,$6,$7,$8)`,
		newUUID(), actorID, role, action, entityType, entityID, success, d)
}

func emitEvent(typ, entityType, entityID, audienceRole string, payload M) {
	p, _ := json.Marshal(payload)
	db.Exec(`INSERT INTO events(type,entity_type,entity_id,audience_role,payload) VALUES($1,$2,$3,$4,$5)`,
		typ, entityType, entityID, audienceRole, p)
	notifyEventListeners()
}

func nullUUID(s *string) any {
	if s == nil || *s == "" {
		return nil
	}
	return *s
}

func strOrEmpty(ns sql.NullString) string {
	if ns.Valid {
		return ns.String
	}
	return ""
}

// requireIdempotency validates and reserves nothing; returns stored response if replay.
// Returns (storedStatus, storedBody, done, err). If done, caller should write stored response.
func idempotencyLookup(userID, endpoint, key string, bodyHash string) (int, string, bool, *apiErr) {
	if key == "" {
		return 0, "", false, errOf(400, "idempotency_required", "idempotencyKey is required")
	}
	var status int
	var body, prevHash string
	err := db.QueryRow(`SELECT response_status, response_body, request_hash FROM idempotency_keys WHERE key=$1 AND user_id=$2 AND endpoint=$3`,
		key, userID, endpoint).Scan(&status, &body, &prevHash)
	if err == nil {
		if prevHash != bodyHash {
			return 0, "", false, errOf(409, "idempotency_conflict", "idempotency key was used with a different request")
		}
		return status, body, true, nil
	}
	return 0, "", false, nil
}

func idempotencyStore(userID, endpoint, key, bodyHash string, status int, body string) {
	db.Exec(`INSERT INTO idempotency_keys(key,user_id,endpoint,request_hash,response_status,response_body) VALUES($1,$2,$3,$4,$5,$6) ON CONFLICT DO NOTHING`,
		key, userID, endpoint, bodyHash, status, body)
}

// idemHandler wraps a handler with idempotency semantics when the request has idempotencyKey.
func respondIdempotent(w http.ResponseWriter, userID, endpoint, key string, rawBody []byte, fn func() (int, any, *apiErr)) {
	bodyHash := hashStr(string(rawBody))
	if key != "" {
		st, body, done, aerr := idempotencyLookup(userID, endpoint, key, bodyHash)
		if aerr != nil {
			writeAPIErr(w, aerr)
			return
		}
		if done {
			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(st)
			w.Write([]byte(body))
			return
		}
	}
	status, payload, aerr := fn()
	if aerr != nil {
		writeAPIErr(w, aerr)
		return
	}
	out, _ := json.Marshal(payload)
	if key != "" && status < 500 {
		idempotencyStore(userID, endpoint, key, bodyHash, status, string(out))
	}
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	w.Write(out)
}

