}

func parseCerts(raw json.RawMessage) ([]certInput, *apiErr) {
	out := []certInput{}
	if len(raw) == 0 {
		return out, nil
	}
	if err := json.Unmarshal(raw, &out); err != nil {
		return nil, errOf(400, "invalid_certification", "certifications must be objects with code and active")
