	}
	var exists bool
	db.QueryRow(`SELECT EXISTS(SELECT 1 FROM users WHERE id=$1)`, userID).Scan(&exists)
	if !exists {
		writeErr(w, 404, "not_found", "user not found")
		return
	}
	roles, e2 := parseRoles(raw["roles"])
	if e2 != nil {
		writeAPIErr(w, e2)
		return
	}
	certs, e3 := parseCerts(raw["certifications"])
	if e3 != nil {
		writeAPIErr(w, e3)
		return
	}
	quals := []string{}
	if rv, ok := raw["qualifications"]; ok {
		json.Unmarshal(rv, &quals)
	}
	active := true
	if rv, ok := raw["active"]; ok {
		json.Unmarshal(rv, &active)
	}
	assignedLoc := ""
