	err := db.QueryRow(`SELECT name,lat,lng,coverage_km,handling_minutes,active,fn_collection_point,fn_transfer_point,fn_hub,fn_laboratory,capacity_units,cooled_capacity_units,reserved_units,cooled_reserved_units FROM locations WHERE id=$1`, id).
		Scan(&name, &lat, &lng, &cov, &hm, &active, &cp, &tp, &hub, &lab, &capU, &coolU, &resU, &coolResU)
	if err != nil {
		return nil
	}
	return M{
		"locationId": id, "id": id, "name": name,
		"coordinate":      M{"latitude": lat, "longitude": lng},
		"coverageKm":      cov, "handlingMinutes": hm, "active": active,
		"functions": M{"collection_point": cp, "transfer_point": tp, "hub": hub, "laboratory": lab},
