	if err != nil {
		return []string{}
	}
	defer rows.Close()
	out := []string{}
	for rows.Next() {
		var s string
		rows.Scan(&s)
		out = append(out, s)
	}
	return out
}

func parseFunctions(raw json.RawMessage) (map[string]bool, *apiErr) {
	out := map[string]bool{}
	if len(raw) == 0 {
		return out, nil
	}
	var arr []string
	if err := json.Unmarshal(raw, &arr); err == nil {
		for _, f := range arr {
			if !validFunctions[f] {
				return nil, errOf(400, "invalid_location_function", "unknown location function: "+f)
			}
			out[f] = true
		}
		return out, nil
	}
	var obj map[string]bool
	if err := json.Unmarshal(raw, &obj); err != nil {
		return nil, errOf(400, "invalid_location_function", "functions must be an array of function names")
	}
	for f, v := range obj {
		if !validFunctions[f] {
			return nil, errOf(400, "invalid_location_function", "unknown location function: "+f)
		}
		if v {
			out[f] = true
		}
	}
	return out, nil
}

