	}
	raw, _, e := decodeRaw(r)
	if e != nil {
		writeAPIErr(w, e)
		return
	}
	var id, name string
	json.Unmarshal(raw["locationId"], &id)
	json.Unmarshal(raw["name"], &name)
	var exists bool
	db.QueryRow(`SELECT EXISTS(SELECT 1 FROM locations WHERE id=$1)`, id).Scan(&exists)
	if !exists {
		writeErr(w, 404, "not_found", "location not found")
		return
	}
	var coord coordinate
	if err := json.Unmarshal(raw["coordinate"], &coord); err != nil || !validCoord(coord) {
		writeErr(w, 400, "invalid_coordinate", "coordinate must contain valid latitude and longitude")
		return
	}
	cov := 5.0
	if rv, ok := raw["coverageKm"]; ok {
		json.Unmarshal(rv, &cov)
		if cov <= 0 || cov > 5 {
			writeErr(w, 400, "invalid_node_coverage", "coverageKm must be in (0, 5]")
			return
		}
	}
	hm := 0
	if rv, ok := raw["handlingMinutes"]; ok {
		json.Unmarshal(rv, &hm)
		if hm < 0 || hm > 1440 {
			writeErr(w, 400, "invalid_handling_time", "handlingMinutes must be in [0, 1440]")
			return
		}
	}
	var fns map[string]bool
