}

// ---- collection request ----

func handleCreateCollectionRequest(w http.ResponseWriter, r *http.Request) {
	s := requireAuth("create_collection_request", true, w, r)
	if s == nil {
		return
	}
	raw, rawBytes, e := decodeRaw(r)
	if e != nil {
		writeAPIErr(w, e)
		return
	}
	var req struct {
		Origin               coordinate `json:"origin"`
		OriginType           string     `json:"originType"`
		OriginNodeID         string     `json:"originNodeId"`
		RequestedAt          string     `json:"requestedAt"`
		DeliveryDeadline     string     `json:"deliveryDeadline"`
		EarliestCollectionAt string     `json:"earliestCollectionAt"`
		LatestCollectionAt   string     `json:"latestCollectionAt"`
		SampleTypeID         string     `json:"sampleTypeId"`
		ContainerType        string     `json:"containerType"`
		TemperatureMinC      float64    `json:"temperatureMinC"`
		TemperatureMaxC      float64    `json:"temperatureMaxC"`
		AlreadySealed        bool       `json:"alreadySealed"`
		IdempotencyKey       string     `json:"idempotencyKey"`
	}
	if err := json.Unmarshal(rawBytes, &req); err != nil {
		writeErr(w, 400, "invalid_json", err.Error())
		return
	}
	respondIdempotent(w, s.userID, "create_collection_request", req.IdempotencyKey, rawBytes, func() (int, any, *apiErr) {
		if !validCoord(req.Origin) {
			return 0, nil, errOf(400, "invalid_coordinate", "origin must contain valid latitude and longitude")
		}
		if req.OriginType != "home" && req.OriginType != "clinic" && req.OriginType != "node" {
			return 0, nil, errOf(400, "invalid_origin_type", "originType must be home, clinic or node")
		}
		if req.OriginType == "node" && req.OriginNodeID == "" {
			return 0, nil, errOf(400, "invalid_origin_type", "originNodeId is required when originType is node")
		}
		if req.AlreadySealed && req.OriginType == "home" {
			return 0, nil, errOf(400, "invalid_origin_type", "pre-sealed samples cannot originate from a home")
		}
		requestedAt, ok := parseTime(req.RequestedAt)
		if !ok {
			return 0, nil, errOf(400, "invalid_time_window", "requestedAt must be RFC3339")
		}
		deadline, ok := parseTime(req.DeliveryDeadline)
		if !ok || !deadline.After(requestedAt) {
			return 0, nil, errOf(400, "invalid_time_window", "deliveryDeadline must be RFC3339 and after requestedAt")
		}
		var earliest, latest *time.Time
		if req.EarliestCollectionAt != "" {
			t, ok := parseTime(req.EarliestCollectionAt)
			if !ok {
				return 0, nil, errOf(400, "invalid_time_window", "earliestCollectionAt must be RFC3339")
			}
			earliest = &t
		}
		if req.LatestCollectionAt != "" {
			t, ok := parseTime(req.LatestCollectionAt)
			if !ok {
				return 0, nil, errOf(400, "invalid_time_window", "latestCollectionAt must be RFC3339")
			}
			latest = &t
		}
		if earliest != nil && latest != nil && latest.Before(*earliest) {
			return 0, nil, errOf(400, "invalid_time_window", "latestCollectionAt must not be before earliestCollectionAt")
		}
		st := loadSampleType(req.SampleTypeID)
		if st == nil {
			return 0, nil, errOf(400, "invalid_sample_type", "sampleTypeId does not reference a known sample type")
		}
		incompat := st.Incompatible
		if incompat == nil {
