			req.SampleTypeID, container, st.TempMin, st.TempMax, arrLiteral(incompat), ternary(svc, "serviceable", "unserviceable"), reason, req.AlreadySealed)
		if dberr != nil {
			return 0, nil, errOf(500, "internal_error", dberr.Error())
