package main

import (
	"encoding/json"
	"net/http"
	"strconv"
	"time"

	"github.com/lib/pq"
)

// ---- list role work ----

func assignmentWorkItem(a *assignmentRow) M {
	m := M{
		"kind": a.Kind, "assignmentId": a.ID, "sampleId": a.SampleID,
		"status": a.Status, "journeyId": a.JourneyID, "sequence": a.Sequence,
		"history": timelineForSample(a.SampleID),
	}
	if a.FromLocationID != nil {
		m["fromLocationId"] = *a.FromLocationID
	}
	if a.ToLocationID != nil {
		m["toLocationId"] = *a.ToLocationID
	}
	if a.NodeID != nil {
		m["nodeId"] = *a.NodeID
	}
	if a.LaboratoryID != nil {
		m["laboratoryId"] = *a.LaboratoryID
		m["destinationCapacity"] = locationJSON(*a.LaboratoryID)["capacity"]
	}
	if a.OfferExpiresAt != nil {
		m["offerExpiresAt"] = fmtTime(*a.OfferExpiresAt)
	}
	return m
}

func sampleWorkItem(sampleID string) M {
	var reqID, status, serviceability string
	var requestedAt, deadline time.Time
	var earliest, latest *time.Time
	var journeyID, labID, holder, requesterID *string
	var recAt *time.Time
	err := db.QueryRow(`SELECT s.request_id, s.status, r.serviceability, r.requested_at, r.delivery_deadline, r.earliest_collection_at, r.latest_collection_at, s.active_journey_id, s.target_laboratory_id, s.current_holder_id, r.requester_id, s.location_recorded_at
		FROM samples s JOIN requests r ON r.id=s.request_id WHERE s.id=$1`, sampleID).
		Scan(&reqID, &status, &serviceability, &requestedAt, &deadline, &earliest, &latest, &journeyID, &labID, &holder, &requesterID, &recAt)
	if err != nil {
		return nil
	}
	m := M{
		"kind": "sample", "sampleId": sampleID, "requestId": reqID, "status": status,
		"serviceability": serviceability, "requestedAt": fmtTime(requestedAt),
		"deliveryDeadline": fmtTime(deadline),
		"history":          timelineForSample(sampleID),
		"locationStale":    isStale(recAt),
	}
	if earliest != nil {
		m["earliestCollectionAt"] = fmtTime(*earliest)
	}
	if latest != nil {
		m["latestCollectionAt"] = fmtTime(*latest)
	}
	if journeyID != nil {
		m["journeyId"] = *journeyID
		m["activeJourneyId"] = *journeyID
	}
	if labID != nil {
		m["laboratoryId"] = *labID
	}
	if holder != nil {
		m["currentHolderId"] = *holder
	}
	if requesterID != nil {
		m["requesterId"] = *requesterID
	}
	if recAt != nil {
		m["locationRecordedAt"] = fmtTime(*recAt)
	}
	return m
}

func journeyWorkItem(j *journeyRow) M {
	var count int
	db.QueryRow(`SELECT count(*) FROM assignments WHERE journey_id=$1`, j.ID).Scan(&count)
	m := M{
		"kind": "journey", "journeyId": j.ID, "status": j.Status, "routeMode": j.RouteMode,
		"planVersion": j.PlanVersion, "sampleIds": journeySampleIDs(j.ID),
		"assignmentCount": count, "history": []M{},
	}
	if j.EstimatedAt != nil {
		m["estimatedDeliveryAt"] = fmtTime(*j.EstimatedAt)
	} else {
		m["estimatedDeliveryAt"] = nil
	}
	return m
}

func handleListRoleWork(w http.ResponseWriter, r *http.Request) {
	s := requireAuth("list_role_work", true, w, r)
	if s == nil {
		return
	}
	var req struct {
		Role string `json:"role"`
	}
	if e := decodeBody(r, &req); e != nil {
		writeAPIErr(w, e)
		return
	}
	if !validRoles[req.Role] {
		writeErr(w, 400, "invalid_role", "unknown role")
		return
	}
	held := false
	for _, ur := range s.roles {
		if ur == req.Role {
			held = true
		}
	}
	if !held {
		writeErr(w, 403, "role_not_held", "role is not assigned to this user")
		return
	}
	pending := []M{}
	inProgress := []M{}
	completed := []M{}
	switch req.Role {
	case "requester":
		rows, _ := db.Query(`SELECT s.id, s.status FROM samples s JOIN requests r ON r.id=s.request_id WHERE r.requester_id=$1 ORDER BY s.created_at`, s.userID)
		var items []struct{ id, status string }
		for rows != nil && rows.Next() {
			var it struct{ id, status string }
			rows.Scan(&it.id, &it.status)
			items = append(items, it)
		}
		if rows != nil {
			rows.Close()
		}
		for _, it := range items {
			m := sampleWorkItem(it.id)
			switch it.status {
			case "received", "cancelled", "expired":
				completed = append(completed, m)
			case "requested", "awaiting_collection":
				pending = append(pending, m)
			default:
				inProgress = append(inProgress, m)
			}
		}
	case "dispatcher", "administrator":
		rows, _ := db.Query(`SELECT id, status FROM journeys ORDER BY created_at DESC LIMIT 200`)
		var js []struct{ id, status string }
		for rows != nil && rows.Next() {
			var it struct{ id, status string }
			rows.Scan(&it.id, &it.status)
			js = append(js, it)
		}
		if rows != nil {
			rows.Close()
		}
		for _, it := range js {
			j := loadJourney(it.id)
			m := journeyWorkItem(j)
			switch it.status {
			case "completed", "cancelled", "expired":
				completed = append(completed, m)
			case "planned":
				pending = append(pending, m)
			default:
				inProgress = append(inProgress, m)
			}
		}
	default:
		// worker roles
		rows, _ := db.Query(`SELECT id, status FROM assignments WHERE offered_to=$1 OR worker_id=$1 ORDER BY created_at DESC LIMIT 300`, s.userID)
		var as []struct{ id, status string }
		for rows != nil && rows.Next() {
			var it struct{ id, status string }
			rows.Scan(&it.id, &it.status)
			as = append(as, it)
		}
		if rows != nil {
			rows.Close()
		}
		for _, it := range as {
			a := loadAssignment(it.id)
			if a == nil {
				continue
			}
			m := assignmentWorkItem(a)
			switch a.Status {
			case "offered":
				if a.OfferedTo != nil && *a.OfferedTo == s.userID {
					pending = append(pending, m)
				}
			case "accepted", "in_progress":
				if a.WorkerID != nil && *a.WorkerID == s.userID {
					inProgress = append(inProgress, m)
				}
			case "completed":
				if a.WorkerID != nil && *a.WorkerID == s.userID {
					completed = append(completed, m)
				}
			}
		}
	}
	audit(s.userID, s.activeRole, "list_role_work", "user", s.userID, true, M{"role": req.Role})
	writeData(w, 200, M{"pending": pending, "inProgress": inProgress, "completed": completed})
}

// ---- journey plan read ----

func journeyPlanJSON(j *journeyRow, viewer *sessionInfo) M {
	sampleIDs := journeySampleIDs(j.ID)
	assignments := journeyAssignments(j.ID)
	legs := []M{}
	assignedWorkers := map[string]bool{}
	var collectionIDs, nodeIDs, labIDs []string
	var firstT, midT, finalT string
	transportIdx := 0
	transportTotal := 0
	for _, a := range assignments {
		if a.Kind == "transport" {
			transportTotal++
		}
	}
	for _, a := range assignments {
		leg := M{"assignmentId": a.ID, "sequence": a.Sequence, "status": a.Status}
		if a.FromLocationID != nil {
			leg["fromLocationId"] = *a.FromLocationID
		}
		if a.ToLocationID != nil {
			leg["toLocationId"] = *a.ToLocationID
		}
		if a.WorkerID != nil {
			leg["workerId"] = *a.WorkerID
			assignedWorkers[*a.WorkerID] = true
		}
		leg["sampleId"] = a.SampleID
		legs = append(legs, leg)
		switch a.Kind {
		case "collection":
			collectionIDs = append(collectionIDs, a.ID)
		case "node":
			nodeIDs = append(nodeIDs, a.ID)
		case "laboratory":
			labIDs = append(labIDs, a.ID)
		case "transport":
			transportIdx++
			if transportIdx == 1 {
				firstT = a.ID
			}
			if transportTotal > 2 && transportIdx == transportTotal-1 {
				midT = a.ID
			}
			if transportIdx == transportTotal {
				finalT = a.ID
			}
		}
	}
	workerIDs := []string{}
	for wid := range assignedWorkers {
		workerIDs = append(workerIDs, wid)
	}
	if collectionIDs == nil {
		collectionIDs = []string{}
	}
	if nodeIDs == nil {
		nodeIDs = []string{}
	}
	if labIDs == nil {
		labIDs = []string{}
	}
	// worker view: only own legs
	if viewer.activeRole != "dispatcher" && viewer.activeRole != "administrator" && viewer.activeRole != "requester" {
		ownLegs := []M{}
		ownIDs := []string{}
		for i, a := range assignments {
			own := (a.WorkerID != nil && *a.WorkerID == viewer.userID) || (a.OfferedTo != nil && *a.OfferedTo == viewer.userID)
			if own {
				ownLegs = append(ownLegs, legs[i])
				ownIDs = append(ownIDs, a.ID)
			}
		}
		m := M{
			"journeyId": j.ID, "planVersion": j.PlanVersion, "routeMode": j.RouteMode,
			"status": j.Status, "scope": "assigned_legs",
			"assignmentIds": ownIDs, "legs": ownLegs, "orderedStops": j.Stops,
			"sampleIds": sampleIDs,
			"collectionAssignmentIds": collectionIDs, "nodeAssignmentIds": nodeIDs,
			"laboratoryAssignmentIds": labIDs, "assignedWorkerIds": workerIDs,
		}
		if j.ParentID != nil {
			m["parentJourneyId"] = *j.ParentID
		}
		if j.EstimatedAt != nil {
			m["estimatedDeliveryAt"] = fmtTime(*j.EstimatedAt)
		}
		return m
	}
	if viewer.activeRole == "requester" {
		m := M{
			"journeyId": j.ID, "routeMode": j.RouteMode, "status": j.Status,
