package main

import (
	"encoding/base64"
	"encoding/json"
	"net/http"
	"strings"
	"sync"
	"time"

	"github.com/gorilla/websocket"
)

var (
	eventMu       sync.Mutex
	eventListeners = map[chan struct{}]bool{}
)

func notifyEventListeners() {
	eventMu.Lock()
	defer eventMu.Unlock()
	for ch := range eventListeners {
		select {
		case ch <- struct{}{}:
		default:
		}
	}
}

var upgrader = websocket.Upgrader{
	CheckOrigin: func(r *http.Request) bool { return true },
}

func eventsSince(since int64, limit int) ([]M, int64) {
	if limit <= 0 || limit > 500 {
		limit = 200
	}
	rows, err := db.Query(`SELECT seq,type,entity_type,entity_id,payload,created_at FROM events WHERE seq > $1 ORDER BY seq LIMIT $2`, since, limit)
	if err != nil {
		return []M{}, since
	}
	defer rows.Close()
	out := []M{}
	cursor := since
	for rows.Next() {
		var seq int64
		var typ, et, eid string
		var payload []byte
		var createdAt time.Time
		rows.Scan(&seq, &typ, &et, &eid, &payload, &createdAt)
		var p M
		json.Unmarshal(payload, &p)
		if p == nil {
			p = M{}
		}
		out = append(out, M{
			"id": seq, "type": typ, "entityType": et, "entityId": eid,
			"payload": p, "createdAt": fmtTime(createdAt),
		})
		cursor = seq
	}
	return out, cursor
}

func handleEvents(w http.ResponseWriter, r *http.Request) {
	// authenticate via Authorization header or websocket subprotocol bearer.<token>
	token := ""
	if h := r.Header.Get("Authorization"); strings.HasPrefix(h, "Bearer ") {
		token = strings.TrimPrefix(h, "Bearer ")
	}
	subproto := r.Header.Get("Sec-WebSocket-Protocol")
	if token == "" && strings.HasPrefix(subproto, "bearer.") {
		dec, err := base64.RawURLEncoding.DecodeString(strings.TrimPrefix(subproto, "bearer."))
		if err == nil {
			token = string(dec)
		} else {
			token = strings.TrimPrefix(subproto, "bearer.")
		}
	}
	sess := lookupSession(token)
	if sess == nil {
		writeErr(w, 401, "unauthorized", "authentication required")
		return
	}
	var since int64
	if v := r.URL.Query().Get("since"); v != "" {
		json.Unmarshal([]byte(v), &since)
	}
	isWS := strings.Contains(strings.ToLower(r.Header.Get("Connection")), "upgrade") &&
		strings.EqualFold(r.Header.Get("Upgrade"), "websocket")
	if !isWS {
		events, cursor := eventsSince(since, 200)
		writeData(w, 200, M{"events": events, "cursor": cursor})
		return
	}
	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		return
	}
	defer conn.Close()
	ch := make(chan struct{}, 1)
	eventMu.Lock()
	eventListeners[ch] = true
	eventMu.Unlock()
	defer func() {
		eventMu.Lock()
		delete(eventListeners, ch)
		eventMu.Unlock()
	}()
	// initial burst
	send := func() bool {
		events, cursor := eventsSince(since, 200)
		since = cursor
		for _, ev := range events {
			if err := conn.WriteJSON(ev); err != nil {
				return false
			}
		}
		return true
	}
	if !send() {
		return
	}
	conn.SetReadDeadline(time.Now().Add(60 * time.Second))
	go func() {
		for {
			if _, _, err := conn.ReadMessage(); err != nil {
				conn.Close()
				return
			}
		}
	}()
	for {
		select {
		case <-ch:
			if !send() {
				return
			}
		case <-time.After(30 * time.Second):
			if err := conn.WriteMessage(websocket.PingMessage, nil); err != nil {
				return
			}
		}
	}
}

