	mux.HandleFunc("/api/decline-assignment", post(handleDeclineAssignment))
	mux.HandleFunc("/api/collect-and-seal-sample", post(handleCollectAndSeal))
	mux.HandleFunc("/api/record-worker-location", post(handleRecordWorkerLocation))
	mux.HandleFunc("/api/update-assignment-progress", post(handleUpdateProgress))
	mux.HandleFunc("/api/initiate-handoff", post(handleInitiateHandoff))
	mux.HandleFunc("/api/confirm-handoff", post(handleConfirmHandoff))
	mux.HandleFunc("/api/record-handling-checkpoint", post(handleRecordCheckpoint))
	mux.HandleFunc("/api/confirm-laboratory-receipt", post(handleConfirmLabReceipt))
	mux.HandleFunc("/api/record-laboratory-exception", post(handleRecordLabException))
	mux.HandleFunc("/api/read-sample-state/{sampleId}", get(handleReadSampleState))
	mux.HandleFunc("/api/read-sample-lifecycle/{sampleId}", get(handleReadSampleLifecycle))
	mux.HandleFunc("/api/list-role-work", post(handleListRoleWork))
	mux.HandleFunc("/api/read-journey-plan", post(handleReadJourneyPlan))
	mux.HandleFunc("/api/read-operations-state", get(handleReadOperationsState))
	mux.HandleFunc("/api/cancel-journey", post(handleCancelJourney))
	mux.HandleFunc("/api/reroute-journey", post(handleRerouteJourney))
	mux.HandleFunc("/api/split-journey", post(handleSplitJourney))
	mux.HandleFunc("/api/merge-journeys", post(handleMergeJourneys))
	mux.HandleFunc("/api/edit-active-plan", post(handleEditActivePlan))
	mux.HandleFunc("/api/report-disruption", post(handleReportDisruption))
	mux.HandleFunc("/api/search-audit-trail", post(handleSearchAudit))
	mux.HandleFunc("/api/create-user", post(handleCreateUser))
	mux.HandleFunc("/api/update-user-access", post(handleUpdateUserAccess))
	mux.HandleFunc("/api/create-location", post(handleCreateLocation))
	mux.HandleFunc("/api/update-location", post(handleUpdateLocation))
	mux.HandleFunc("/api/create-connection", post(handleCreateConnection))
	mux.HandleFunc("/api/create-sample-type", post(handleCreateSampleType))
	mux.HandleFunc("/api/update-sample-type", post(handleUpdateSampleType))
	mux.HandleFunc("/api/set-location-status", post(handleSetLocationStatus))
	mux.HandleFunc("/api/set-location-function-status", post(handleSetLocationFunctionStatus))
	mux.HandleFunc("/api/set-connection-status", post(handleSetConnectionStatus))
	mux.HandleFunc("/api/configure-capacity", post(handleConfigureCapacity))
	mux.HandleFunc("/api/configure-laboratory-acceptance", post(handleConfigureLabAcceptance))
	mux.HandleFunc("/api/set-worker-availability", post(handleSetWorkerAvailability))
	mux.HandleFunc("/api/read-serviceability-snapshot", get(handleReadServiceabilitySnapshot))
	mux.HandleFunc("/api/events", handleEvents)
	mux.HandleFunc("/api/ui/bootstrap", get(handleUIBootstrap))
	mux.HandleFunc("/api/openapi.json", get(func(w http.ResponseWriter, r *http.Request) {
		http.ServeFile(w, r, openapiPath())
	}))

	// static assets: map-assets and frontend
	webDir := os.Getenv("WEB_DIR")
	if webDir == "" {
		webDir = "/workspace/web/dist"
	}
	mapDir := os.Getenv("MAP_ASSETS_DIR")
	if mapDir == "" {
		mapDir = "/workspace/assets/map-assets"
	}
	mux.Handle("/map-assets/", http.StripPrefix("/map-assets/", http.FileServer(http.Dir(mapDir))))
	mux.HandleFunc("/", spaHandler(webDir))

