}

func openapiPath() string {
	if p := os.Getenv("OPENAPI_PATH"); p != "" {
		return p
	}
	return "/workspace/app-setup/openapi.json"
}

func spaHandler(dir string) http.HandlerFunc {
	fs := http.FileServer(http.Dir(dir))
	return func(w http.ResponseWriter, r *http.Request) {
		p := filepath.Join(dir, filepath.Clean(r.URL.Path))
		if st, err := os.Stat(p); err == nil && !st.IsDir() {
			fs.ServeHTTP(w, r)
			return
		}
		http.ServeFile(w, r, filepath.Join(dir, "index.html"))
	}
}

func handleUIBootstrap(w http.ResponseWriter, r *http.Request) {
	s := requireAuth("ui_bootstrap", false, w, r)
	if s == nil {
		return
	}
	sampleTypes := []M{}
	rows, _ := db.Query(`SELECT id FROM sample_types ORDER BY name`)
	if rows != nil {
		for rows.Next() {
			var id string
			rows.Scan(&id)
			sampleTypes = append(sampleTypes, sampleTypeJSON(id))
		}
		rows.Close()
	}
	writeData(w, 200, M{
		"user":        readUserByIDMust(s.userID),
		"activeRole":  s.activeRole,
		"roles":       s.roles,
		"sampleTypes": sampleTypes,
		"mapStyle":    "/map-assets/style.json",
	})
}

func readUserByIDMust(id string) M {
	m, _ := readUserByID(id)
	if m == nil {
		return M{"userId": id}
	}
	return m
}

var _ = json.Marshal

