package main

import (
	"strconv"
	"container/heap"
	"encoding/json"
	"time"

	"github.com/lib/pq"
)

type sampleTypeInfo struct {
	ID             string
	Name           string
	QualRequired   bool
	RequiredQual   string
	ContainerType  string
	TempMin        float64
	TempMax        float64
	Incompatible   []string
	RequiresCooled bool
	BatchingAllowed bool
}

func loadSampleType(id string) *sampleTypeInfo {
	var st sampleTypeInfo
	err := db.QueryRow(`SELECT id,name,qualified_collector_required,required_qualification,container_type,temp_min,temp_max,incompatible_sample_types,requires_cooled_route,batching_allowed FROM sample_types WHERE id=$1`, id).
		Scan(&st.ID, &st.Name, &st.QualRequired, &st.RequiredQual, &st.ContainerType, &st.TempMin, &st.TempMax, pq.Array(&st.Incompatible), &st.RequiresCooled, &st.BatchingAllowed)
	if err != nil {
		return nil
	}
	return &st
}

type locInfo struct {
	ID       string
	Name     string
	Lat, Lng float64
	CovKm    float64
	Handling int
	Active   bool
	CP, TP, Hub, Lab bool
	CapU, CoolU, ResU, CoolResU int
}

func loadLocations() map[string]*locInfo {
	rows, err := db.Query(`SELECT id,name,lat,lng,coverage_km,handling_minutes,active,fn_collection_point,fn_transfer_point,fn_hub,fn_laboratory,capacity_units,cooled_capacity_units,reserved_units,cooled_reserved_units FROM locations`)
	if err != nil {
		return map[string]*locInfo{}
	}
	defer rows.Close()
	out := map[string]*locInfo{}
	for rows.Next() {
		var l locInfo
		rows.Scan(&l.ID, &l.Name, &l.Lat, &l.Lng, &l.CovKm, &l.Handling, &l.Active, &l.CP, &l.TP, &l.Hub, &l.Lab, &l.CapU, &l.CoolU, &l.ResU, &l.CoolResU)
		out[l.ID] = &l
	}
	return out
}

type connInfo struct {
	ID, From, To string
	Travel       int
	Cost         float64
	Cooled, Active bool
	CapU, CoolU, ResU, CoolResU int
}

func loadConnections() []*connInfo {
	rows, err := db.Query(`SELECT id,from_location_id,to_location_id,travel_minutes,cost_units,cooled,active,capacity_units,cooled_capacity_units,reserved_units,cooled_reserved_units FROM connections`)
	if err != nil {
		return nil
	}
	defer rows.Close()
	var out []*connInfo
	for rows.Next() {
		var c connInfo
		rows.Scan(&c.ID, &c.From, &c.To, &c.Travel, &c.Cost, &c.Cooled, &c.Active, &c.CapU, &c.CoolU, &c.ResU, &c.CoolResU)
		out = append(out, &c)
	}
	return out
}

// ---- Dijkstra over locations ----

type pathResult struct {
	Nodes     []string // location ids in order, including entry and lab
	Conns     []*connInfo
	Minutes   int
	Cost      float64
	HasCapacity bool
}

type pqItem struct {
	node string
	dist int
}
type minHeap []pqItem

func (h minHeap) Len() int            { return len(h) }
func (h minHeap) Less(i, j int) bool  { return h[i].dist < h[j].dist }
func (h minHeap) Swap(i, j int)       { h[i], h[j] = h[j], h[i] }
func (h *minHeap) Push(x any)         { *h = append(*h, x.(pqItem)) }
func (h *minHeap) Pop() any {
	old := *h
	n := len(old)
	it := old[n-1]
	*h = old[:n-1]
	return it
}

// findRoute computes the shortest-time path from entry node to any accepting lab.
// checkCapacity: require available capacity on connections and intermediate nodes.
func findRoute(locs map[string]*locInfo, conns []*connInfo, entryID string, acceptingLabs map[string]bool, needCooled bool, checkCapacity bool) *pathResult {
	adj := map[string][]*connInfo{}
	for _, c := range conns {
		if !c.Active {
			continue
		}
		if needCooled && !c.Cooled {
			continue
		}
		adj[c.From] = append(adj[c.From], c)
	}
	dist := map[string]int{entryID: 0}
	prev := map[string]*connInfo{}
	h := &minHeap{{entryID, 0}}
	heap.Init(h)
	best := ""
	for h.Len() > 0 {
		it := heap.Pop(h).(pqItem)
		if d, ok := dist[it.node]; ok && it.dist > d {
			continue
		}
		if acceptingLabs[it.node] {
			best = it.node
			break
		}
		for _, c := range adj[it.node] {
			to := locs[c.To]
			if to == nil || !to.Active {
				continue
			}
			nd := it.dist + c.Travel + to.Handling
			if cur, ok := dist[c.To]; !ok || nd < cur {
				dist[c.To] = nd
				prev[c.To] = c
				heap.Push(h, pqItem{c.To, nd})
			}
		}
	}
	if best == "" {
		return nil
	}
	// reconstruct
	var revConns []*connInfo
	for n := best; n != entryID; {
		c := prev[n]
		revConns = append([]*connInfo{c}, revConns...)
		n = c.From
	}
	nodes := []string{entryID}
	total := 0
	cost := 0.0
	hasCap := true
	for _, c := range revConns {
		nodes = append(nodes, c.To)
		total += c.Travel + locs[c.To].Handling
		cost += c.Cost
		if checkCapacity {
			if needCooled {
				if c.CoolU-c.CoolResU < 1 {
					hasCap = false
				}
			} else if c.CapU-c.ResU < 1 {
				hasCap = false
			}
		}
	}
	if checkCapacity {
		// intermediate nodes and lab need capacity
		for _, nid := range nodes[1:] {
			l := locs[nid]
			if needCooled {
				if l.CoolU-l.CoolResU < 1 {
					hasCap = false
				}
			} else if l.CapU-l.ResU < 1 {
				hasCap = false
			}
		}
	}
	return &pathResult{Nodes: nodes, Conns: revConns, Minutes: total, Cost: cost, HasCapacity: hasCap}
}

// serviceabilityCheck performs the dry-run check. Returns (serviceable, reason, labID, eta).
func serviceabilityCheck(originLat, originLng float64, originType, originNodeID string, st *sampleTypeInfo, requestedAt time.Time, deadline time.Time, earliest *time.Time) (bool, string, string, time.Time) {
	locs := loadLocations()
	conns := loadConnections()
	// entry nodes
	var entries []*locInfo
	if originType == "node" && originNodeID != "" {
		if l, ok := locs[originNodeID]; ok && l.Active && l.CP {
			entries = append(entries, l)
		}
	} else {
		for _, l := range locs {
			if l.Active && l.CP && haversineKm(originLat, originLng, l.Lat, l.Lng) <= l.CovKm {
				entries = append(entries, l)
			}
		}
	}
	if len(entries) == 0 {
		return false, "outside_service_coverage", "", time.Time{}
	}
	accepting := map[string]bool{}
	for _, l := range locs {
		if l.Active && l.Lab {
			for _, stID := range labAcceptances(l.ID) {
				if stID == st.ID {
					accepting[l.ID] = true
				}
			}
		}
	}
	if len(accepting) == 0 {
		return false, "no_accepting_laboratory", "", time.Time{}
	}
	start := requestedAt
	if earliest != nil && earliest.After(start) {
		start = *earliest
	}
	var bestPath *pathResult
	var bestEntry *locInfo
	for _, e := range entries {
		p := findRoute(locs, conns, e.ID, accepting, st.RequiresCooled, false)
		if p == nil {
			continue
		}
		if bestPath == nil || p.Minutes < bestPath.Minutes {
			bestPath = p
			bestEntry = e
		}
	}
	if bestPath == nil {
		if st.RequiresCooled {
			// maybe a non-cooled route exists but handling cannot be satisfied
			any := false
			for _, e := range entries {
				if findRoute(locs, conns, e.ID, accepting, false, false) != nil {
					any = true
				}
			}
			if any {
				return false, "handling_rules_unsatisfiable", "", time.Time{}
			}
		}
		return false, "no_route", "", time.Time{}
	}
	// capacity-aware route
	capPath := findRoute(locs, conns, bestEntry.ID, accepting, st.RequiresCooled, true)
	if capPath == nil || !capPath.HasCapacity {
		return false, "insufficient_capacity", "", time.Time{}
	}
	// origin travel estimate: 2 min per km at 30km/h
	originKm := haversineKm(originLat, originLng, bestEntry.Lat, bestEntry.Lng)
	originMin := int(originKm * 2)
	eta := start.Add(time.Duration(originMin+capPath.Minutes) * time.Minute)
	if eta.After(deadline) {
		return false, "deadline_unreachable", "", eta
	}
	labID := capPath.Nodes[len(capPath.Nodes)-1]
	return true, "serviceable", labID, eta
}

// ---- serviceability snapshot ----

func recomputeServiceabilitySnapshot() {
	locs := loadLocations()
	regions := []M{}
	activeCP := 0
	for _, l := range locs {
		if l.Active && l.CP {
			activeCP++
			regions = append(regions, M{
				"locationId": l.ID, "name": l.Name,
				"latitude": l.Lat, "longitude": l.Lng, "coverageKm": l.CovKm,
			})
		}
	}
	payload, _ := json.Marshal(M{"regions": regions, "activeCollectionPointCount": activeCP})
	var maxV int
	db.QueryRow(`SELECT COALESCE(MAX(version),0) FROM serviceability_snapshots`).Scan(&maxV)
	db.Exec(`INSERT INTO serviceability_snapshots(version,status,computed_at,network_revision,payload) VALUES($1,'complete',now(),$2,$3)`,
		maxV+1, networkRevision(), payload)
}

func currentServiceabilityVersion() int {
	var v int
	err := db.QueryRow(`SELECT COALESCE(MAX(version),0) FROM serviceability_snapshots WHERE status='complete'`).Scan(&v)
	if err != nil {
		return 0
	}
	return v
}

// ---- offers ----

func offerTimeout() time.Duration {
	return 60 * time.Second
}

// eligibleWorkers returns candidate workers for an assignment in fair order.
func eligibleWorkers(a *assignmentRow, st *sampleTypeInfo) []string {
	var role string
	switch a.Kind {
	case "collection":
		role = "collection_professional"
	case "transport":
		role = "delivery_partner"
	case "node":
		role = "node_handler"
	case "laboratory":
		role = "laboratory_team"
	}
	args := []any{role}
	q := `SELECT u.id FROM users u JOIN user_roles r ON r.user_id=u.id AND r.role=$1 WHERE u.active AND u.available`
	if a.Kind == "node" && a.NodeID != nil {
		args = append(args, *a.NodeID)
		q += ` AND u.assigned_location_id = $2`
	}
	if a.Kind == "laboratory" && a.LaboratoryID != nil {
		args = append(args, *a.LaboratoryID)
		q += ` AND u.assigned_location_id = $2`
	}
	if a.Kind == "collection" && st != nil && st.QualRequired {
		args = append(args, st.RequiredQual)
		p := itoa(len(args))
		q += ` AND (EXISTS(SELECT 1 FROM user_qualifications q WHERE q.user_id=u.id AND q.code=$` + p + `) OR EXISTS(SELECT 1 FROM user_certifications c WHERE c.user_id=u.id AND c.code=$` + p + ` AND c.active AND (c.expires_at IS NULL OR c.expires_at > now())))`
	}
	args = append(args, a.ID)
	p := itoa(len(args))
	q += ` AND u.id <> ALL(COALESCE((SELECT declined_by FROM assignments WHERE id=$` + p + `), '{}'))`
	q += ` ORDER BY (u.decline_penalty_until IS NOT NULL AND u.decline_penalty_until > now()) ASC,
		(SELECT count(*) FROM assignments x WHERE x.worker_id=u.id AND x.status IN ('accepted','in_progress')) ASC,
		u.last_assigned_at ASC NULLS FIRST, u.id ASC`
	rows, err := db.Query(q, args...)
	if err != nil {
		return nil
	}
	defer rows.Close()
	out := []string{}
	for rows.Next() {
		var id string
		rows.Scan(&id)
		out = append(out, id)
	}
	return out
}

func itoa(i int) string { return strconv.Itoa(i) }

// offerAssignment offers a pending assignment to the next eligible worker.
// Returns (offeredTo, exceptionFlagged).
func offerAssignment(a *assignmentRow) (string, bool) {
	st := loadSampleType(requestSampleType(a.SampleID))
	candidates := eligibleWorkers(a, st)
	if len(candidates) == 0 {
		// no qualified worker available
		markSampleException(a.SampleID, "no_qualified_worker", "no qualified worker is available for assignment "+a.ID)
		db.Exec(`UPDATE assignments SET status='exception' WHERE id=$1 AND status='pending'`, a.ID)
		return "", true
	}
	w := candidates[0]
	exp := time.Now().Add(offerTimeout())
	db.Exec(`UPDATE assignments SET offered_to=$1, offer_expires_at=$2, offer_round=offer_round+1, status='offered' WHERE id=$3 AND status IN ('pending','offered')`, w, exp, a.ID)
	db.Exec(`UPDATE users SET last_assigned_at=now() WHERE id=$1`, w)
	emitEvent("assignment_offered", "assignment", a.ID, "", M{"assignmentId": a.ID, "workerId": w, "kind": a.Kind, "sampleId": a.SampleID})
	return w, false
}

func requestSampleType(sampleID string) string {
	var stID string
	db.QueryRow(`SELECT r.sample_type_id FROM samples s JOIN requests r ON r.id=s.request_id WHERE s.id=$1`, sampleID).Scan(&stID)
	return stID
}

func markSampleException(sampleID, reason, msg string) {
	ex, _ := json.Marshal(M{"reason": reason, "message": msg, "at": fmtTime(time.Now())})
	db.Exec(`UPDATE samples SET status='exception', exception=$1 WHERE id=$2 AND status NOT IN ('received','cancelled','expired')`, ex, sampleID)
	emitEvent("sample_exception", "sample", sampleID, "dispatcher", M{"sampleId": sampleID, "reason": reason})
}

// sweepExpiredOffers treats unanswered offers as declines and re-offers.
func sweepExpiredOffers() {
	rows, err := db.Query(`SELECT id FROM assignments WHERE status='offered' AND offer_expires_at < now()`)
	if err != nil {
		return
	}
	var ids []string
	for rows.Next() {
		var id string
		rows.Scan(&id)
		ids = append(ids, id)
	}
	rows.Close()
	for _, id := range ids {
		a := loadAssignment(id)
		if a == nil || a.OfferedTo == nil {
			continue
		}
		db.Exec(`UPDATE assignments SET status='pending', declined_by = array_append(declined_by, $1), offered_to=NULL, offer_expires_at=NULL WHERE id=$2 AND status='offered'`, *a.OfferedTo, id)
		db.Exec(`UPDATE users SET decline_penalty_until = now() + interval '10 minutes' WHERE id=$1`, *a.OfferedTo)
		emitEvent("offer_expired", "assignment", id, "", M{"assignmentId": id, "workerId": *a.OfferedTo})
		a2 := loadAssignment(id)
		offerAssignment(a2)
	}
}

// maybeOfferNext offers pending assignments whose prerequisites are satisfied.
func maybeOfferNext(journeyID string) {
	rows, err := db.Query(`SELECT id FROM assignments WHERE journey_id=$1 AND status='pending' ORDER BY sequence`, journeyID)
	if err != nil {
		return
	}
	var ids []string
	for rows.Next() {
		var id string
		rows.Scan(&id)
		ids = append(ids, id)
	}
	rows.Close()
	for _, id := range ids {
		a := loadAssignment(id)
		if a == nil {
			continue
		}
		if !assignmentPrereqsMet(a) {
			continue
		}
		offerAssignment(a)
	}
}

// assignmentPrereqsMet: an assignment can be offered when all lower-sequence
// assignments in the journey are completed (or for first transport leg, collection completed).
func assignmentPrereqsMet(a *assignmentRow) bool {
	var incomplete int
	db.QueryRow(`SELECT count(*) FROM assignments WHERE journey_id=$1 AND sequence < $2 AND status NOT IN ('completed','cancelled')`, a.JourneyID, a.Sequence).Scan(&incomplete)
	return incomplete == 0
}

