// ---- collect and seal ----

func handleCollectAndSeal(w http.ResponseWriter, r *http.Request) {
	s := requireAuth("collect_and_seal_sample", true, w, r)
	if s == nil {
		return
	}
	_, rawBytes, e := decodeRaw(r)
	if e != nil {
		writeAPIErr(w, e)
		return
	}
	var req struct {
		AssignmentID     string      `json:"assignmentId"`
		ObservedAt       string      `json:"observedAt"`
		ObservedLocation coordinate  `json:"observedLocation"`
		ContainerType    string      `json:"containerType"`
		ObservedTempC    float64     `json:"observedTemperatureC"`
		IdempotencyKey   string      `json:"idempotencyKey"`
	}
	json.Unmarshal(rawBytes, &req)
	respondIdempotent(w, s.userID, "collect_and_seal_sample", req.IdempotencyKey, rawBytes, func() (int, any, *apiErr) {
		a := loadAssignment(req.AssignmentID)
		if a == nil {
			return 0, nil, errOf(404, "not_found", "assignment not found")
		}
		if a.Kind != "collection" {
			return 0, nil, errOf(409, "invalid_assignment_state", "assignment is not a collection assignment")
		}
		if a.WorkerID == nil || *a.WorkerID != s.userID || (a.Status != "accepted" && a.Status != "in_progress") {
			return 0, nil, errOf(409, "invalid_assignment_state", "assignment is not accepted by you")
		}
		observedAt, ok := parseTime(req.ObservedAt)
		if !ok {
			return 0, nil, errOf(400, "invalid_time_window", "observedAt must be RFC3339")
		}
		// collection window check
		var earliest, latest *time.Time
		db.QueryRow(`SELECT r.earliest_collection_at, r.latest_collection_at FROM samples sm JOIN requests r ON r.id=sm.request_id WHERE sm.id=$1`, a.SampleID).Scan(&earliest, &latest)
		if earliest != nil && observedAt.Before(*earliest) {
			return 0, nil, errOf(409, "collection_window_missed", "collection is before the collection window")
		}
		if latest != nil && observedAt.After(*latest) {
			markSampleException(a.SampleID, "collection_window_missed", "collection occurred after the collection window")
			return 0, nil, errOf(409, "collection_window_missed", "collection occurred after the collection window")
		}
		st := loadSampleType(requestSampleType(a.SampleID))
		compliant := true
		if req.ContainerType != "" && st.ContainerType != "" && req.ContainerType != st.ContainerType {
			compliant = false
		}
		if req.ObservedTempC < st.TempMin || req.ObservedTempC > st.TempMax {
			compliant = false
		}
		var sealed bool
		db.QueryRow(`SELECT sealed FROM samples WHERE id=$1`, a.SampleID).Scan(&sealed)
		if sealed {
			return 0, nil, errOf(409, "already_sealed", "sample is already sealed")
		}
		db.Exec(`UPDATE samples SET sealed=TRUE, sealed_at=$1, status='sealed', current_holder_id=$2, last_lat=$3, last_lng=$4, location_recorded_at=now() WHERE id=$5`,
			observedAt, s.userID, req.ObservedLocation.Latitude, req.ObservedLocation.Longitude, a.SampleID)
		db.Exec(`UPDATE assignments SET status='completed', completed_at=now() WHERE id=$1`, a.ID)
		db.Exec(`INSERT INTO checkpoints(id,sample_id,assignment_id,container_type,observed_temp,compliant,recorded_at,recorded_by) VALUES($1,$2,$3,$4,$5,$6,$7,$8)`,
			newUUID(), a.SampleID, a.ID, req.ContainerType, req.ObservedTempC, compliant, observedAt, s.userID)
		audit(s.userID, s.activeRole, "collect_and_seal_sample", "sample", a.SampleID, true, M{"assignmentId": a.ID, "compliant": compliant})
		emitEvent("sample_sealed", "sample", a.SampleID, "", M{"sampleId": a.SampleID})
		if !compliant {
			markSampleException(a.SampleID, "temperature_out_of_range", "observed container or temperature outside required range at collection")
		}
		maybeOfferNext(a.JourneyID)
		return 201, M{"data": M{"sampleId": a.SampleID, "sealed": true, "compliant": compliant, "sealedAt": fmtTime(observedAt)}}, nil
	})
}

// ---- worker location ----

func handleRecordWorkerLocation(w http.ResponseWriter, r *http.Request) {
	s := requireAuth("record_worker_location", true, w, r)
	if s == nil {
		return
	}
	var req struct {
		AssignmentID string     `json:"assignmentId"`
		Coordinate   coordinate `json:"coordinate"`
		Sequence     int        `json:"sequence"`
		RecordedAt   string     `json:"recordedAt"`
	}
	if e := decodeBody(r, &req); e != nil {
		writeAPIErr(w, e)
		return
	}
	if !validCoord(req.Coordinate) {
		writeErr(w, 400, "invalid_coordinate", "coordinate must contain valid latitude and longitude")
		return
	}
	a := loadAssignment(req.AssignmentID)
	if a == nil {
		writeErr(w, 404, "not_found", "assignment not found")
		return
	}
	if a.WorkerID == nil || *a.WorkerID != s.userID {
		writeErr(w, 403, "forbidden", "assignment is not yours")
		return
	}
	recordedAt := time.Now()
	if req.RecordedAt != "" {
		if t, ok := parseTime(req.RecordedAt); ok {
			recordedAt = t
		}
	}
	var lastSeq int
	db.QueryRow(`SELECT COALESCE(MAX(sequence),0) FROM worker_locations WHERE worker_id=$1`, s.userID).Scan(&lastSeq)
	if req.Sequence <= lastSeq {
		writeErr(w, 409, "stale_location", "location sequence is not newer than the last recorded location")
		return
	}
	db.Exec(`INSERT INTO worker_locations(id,worker_id,assignment_id,lat,lng,sequence,recorded_at) VALUES($1,$2,$3,$4,$5,$6,$7)`,
		newUUID(), s.userID, req.AssignmentID, req.Coordinate.Latitude, req.Coordinate.Longitude, req.Sequence, recordedAt)
	db.Exec(`UPDATE users SET last_lat=$1, last_lng=$2, location_recorded_at=$3 WHERE id=$4`,
		req.Coordinate.Latitude, req.Coordinate.Longitude, recordedAt, s.userID)
	// update sample location if worker currently holds it
	db.Exec(`UPDATE samples SET last_lat=$1, last_lng=$2, location_recorded_at=$3 WHERE current_holder_id=$4 AND status NOT IN ('received','cancelled','expired')`,
		req.Coordinate.Latitude, req.Coordinate.Longitude, recordedAt, s.userID)
	audit(s.userID, s.activeRole, "record_worker_location", "assignment", req.AssignmentID, true, M{"sequence": req.Sequence})
	emitEvent("worker_location", "worker", s.userID, "dispatcher", M{"workerId": s.userID, "latitude": req.Coordinate.Latitude, "longitude": req.Coordinate.Longitude})
	writeData(w, 201, M{"workerId": s.userID, "assignmentId": req.AssignmentID, "sequence": req.Sequence, "stale": false})
}

