[?2004lfunc handleAuthenticate(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Username string `json:"username"`
		Password string `json:"password"`
	}
	if e := decodeBody(r, &req); e != nil {
		writeAPIErr(w, e)
		return
	}
	var userID, hash string
	var active bool
	err := db.QueryRow(`SELECT id, password_hash, active FROM users WHERE username=$1`, req.Username).Scan(&userID, &hash, &active)
	if err != nil || !active || bcrypt.CompareHashAndPassword([]byte(hash), []byte(req.Password)) != nil {
		audit("", "", "authenticate_user", "user", req.Username, false, M{"reason": "invalid_credentials"})
		writeErr(w, 401, "invalid_credentials", "invalid username or password")
		return
	}
	token := newToken()
	db.Exec(`INSERT INTO sessions(token,user_id,expires_at) VALUES($1,$2,$3)`, token, userID, time.Now().Add(24*time.Hour))
	roles := userRoles(userID)
	activeRole := ""
	if len(roles) == 1 {
		activeRole = roles[0]
		db.Exec(`UPDATE sessions SET active_role=$1 WHERE token=$2`, activeRole, token)
	}
	audit(userID, activeRole, "authenticate_user", "user", userID, true, M{"username": req.Username})
	writeData(w, 200, M{
		"sessionToken": token,
		"userId":       userID,
		"roles":        roles,
		"activeRole":   activeRole,
	})
}

func handleSelectActiveRole(w http.ResponseWriter, r *http.Request) {
	s := requireAuth("select_active_role", false, w, r)
	if s == nil {
		return
	}
	var raw struct {
		Role json.RawMessage `json:"role"`
	}
	if e := decodeBody(r, &raw); e != nil {
		writeAPIErr(w, e)
		return
	}
	var role string
	if err := json.Unmarshal(raw.Role, &role); err != nil || !validRoles[role] {
		writeErr(w, 400, "invalid_role", "role must be one of the known role names")
		return
	}
	held := false
	for _, ur := range s.roles {
		if ur == role {
			held = true
		}
	}
	if !held {
		audit(s.userID, s.activeRole, "select_active_role", "user", s.userID, false, M{"role": role})
		writeErr(w, 403, "role_not_held", "the selected role is not assigned to this user")
		return
	}
	db.Exec(`UPDATE sessions SET active_role=$1 WHERE token=$2`, role, s.token)
	audit(s.userID, role, "select_active_role", "user", s.userID, true, M{"role": role})
	writeData(w, 200, M{"activeRole": role, "roles": s.roles})
}

func handleReadUser(w http.ResponseWriter, r *http.Request) {
	s := requireAuth("read_user", false, w, r)
	if s == nil {
		return
	}
	id := r.PathValue("userId")
	if s.userID != id && s.activeRole != "administrator" && s.activeRole != "dispatcher" {
		writeErr(w, 403, "forbidden", "cannot read another user")
		return
