func handleUpdateProgress(w http.ResponseWriter, r *http.Request) {
	s := requireAuth("update_assignment_progress", true, w, r)
	if s == nil {
		return
	}
	var req struct {
		AssignmentID string `json:"assignmentId"`
		Status       string `json:"status"`
	}
	if e := decodeBody(r, &req); e != nil {
		writeAPIErr(w, e)
		return
	}
	a := loadAssignment(req.AssignmentID)
	if a == nil {
		writeErr(w, 404, "not_found", "assignment not found")
		return
	}
	if a.WorkerID == nil || *a.WorkerID != s.userID {
		writeErr(w, 403, "forbidden", "assignment is not yours")
		return
	}
	if a.Status != "accepted" && a.Status != "in_progress" {
		writeErr(w, 409, "invalid_assignment_state", "assignment is not active")
		return
	}
	db.Exec(`UPDATE assignments SET status='in_progress', progress_status=$1 WHERE id=$2`, req.Status, a.ID)
