func arrLiteral(items []string) any {
	if items == nil {
		items = []string{}
	}
	return "{" + joinQuoted(items) + "}"
}

func joinQuoted(items []string) string {
	out := ""
	for i, it := range items {
		if i > 0 {
			out += ","
		}
		out += it
	}
	return out
}

