				resp["activeAssignmentIds"] = activeAssignmentIDs(sampleID)
			} else {
				resp["serviceabilityReason"] = jerr.code
			}
		}
		emitEvent("request_created", "request", reqID, "", M{"requestId": reqID, "sampleId": sampleID})
		return 201, M{"data": resp}, nil
	})
}

func activeAssignmentIDs(sampleID string) []string {
	rows, err := db.Query(`SELECT id FROM assignments WHERE sample_id=$1 AND status IN ('pending','offered','accepted','in_progress') ORDER BY sequence`, sampleID)
	if err != nil {
		return []string{}
	}
	defer rows.Close()
	out := []string{}
	for rows.Next() {
		var id string
		rows.Scan(&id)
		out = append(out, id)
	}
	return out
}

