	}
	if req.Status == "en_route" {
		db.Exec(`UPDATE samples SET status='in_transit' WHERE id=$1 AND status IN ('sealed','at_node')`, a.SampleID)
	}
	audit(s.userID, s.activeRole, "update_assignment_progress", "assignment", a.ID, true, M{"status": req.Status})
	emitEvent("assignment_progress", "assignment", a.ID, "", M{"assignmentId": a.ID, "status": req.Status})
	writeData(w, 201, M{"assignmentId": a.ID, "status": req.Status})
