// ---- serviceability ----

func handleCheckServiceability(w http.ResponseWriter, r *http.Request) {
	s := requireAuth("check_serviceability", true, w, r)
	if s == nil {
		return
	}
	var req struct {
		Origin              coordinate `json:"origin"`
		OriginType          string     `json:"originType"`
		OriginNodeID        string     `json:"originNodeId"`
		RequestedAt         string     `json:"requestedAt"`
		DeliveryDeadline    string     `json:"deliveryDeadline"`
		EarliestCollectionAt string    `json:"earliestCollectionAt"`
		SampleTypeID        string     `json:"sampleTypeId"`
		ContainerType       string     `json:"containerType"`
		TemperatureMinC     float64    `json:"temperatureMinC"`
		TemperatureMaxC     float64    `json:"temperatureMaxC"`
	}
	if e := decodeBody(r, &req); e != nil {
		writeAPIErr(w, e)
		return
	}
	if !validCoord(req.Origin) {
		writeErr(w, 400, "invalid_coordinate", "origin must contain valid latitude and longitude")
		return
	}
	if req.OriginType != "home" && req.OriginType != "clinic" && req.OriginType != "node" {
		writeErr(w, 400, "invalid_origin_type", "originType must be home, clinic or node")
		return
	}
	if req.OriginType == "node" && req.OriginNodeID == "" {
		writeErr(w, 400, "invalid_origin_type", "originNodeId is required when originType is node")
		return
	}
	requestedAt, ok := parseTime(req.RequestedAt)
	if !ok {
		writeErr(w, 400, "invalid_time_window", "requestedAt must be RFC3339")
		return
	}
	deadline, ok := parseTime(req.DeliveryDeadline)
	if !ok || !deadline.After(requestedAt) {
		writeErr(w, 400, "invalid_time_window", "deliveryDeadline must be RFC3339 and after requestedAt")
		return
	}
	var earliest *time.Time
	if req.EarliestCollectionAt != "" {
		if t, ok := parseTime(req.EarliestCollectionAt); ok {
			earliest = &t
		}
	}
	st := loadSampleType(req.SampleTypeID)
	if st == nil {
		writeErr(w, 400, "invalid_sample_type", "sampleTypeId does not reference a known sample type")
