		return 201, M{"data": M{
			"requestId": reqID, "sampleId": sampleID, "journeyId": journeyID,
			"serviceability": "serviceable", "targetLaboratoryId": labID,
			"activeAssignmentIds":  activeAssignmentIDs(sampleID),
			"earliestCollectionAt": fmtTime(requestedAt),
			"latestCollectionAt":   fmtTime(deadline),
			"alreadySealed":        true,
			"originType":           req.OriginType,
		}}, nil
	})
}

