	}
	writeData(w, 201, M{"checkpointId": id, "compliant": compliant})
}

// ---- laboratory receipt / exception ----

func handleConfirmLabReceipt(w http.ResponseWriter, r *http.Request) {
	s := requireAuth("confirm_laboratory_receipt", true, w, r)
	if s == nil {
		return
	}
	_, rawBytes, e := decodeRaw(r)
	if e != nil {
		writeAPIErr(w, e)
		return
	}
	var req struct {
		AssignmentID   string  `json:"assignmentId"`
		ObservedTempC  float64 `json:"observedTemperatureC"`
		IdempotencyKey string  `json:"idempotencyKey"`
	}
	json.Unmarshal(rawBytes, &req)
	respondIdempotent(w, s.userID, "confirm_laboratory_receipt", req.IdempotencyKey, rawBytes, func() (int, any, *apiErr) {
		a := loadAssignment(req.AssignmentID)
		if a == nil {
			return 0, nil, errOf(404, "not_found", "assignment not found")
		}
		if a.Kind != "laboratory" {
			return 0, nil, errOf(409, "invalid_assignment_state", "assignment is not a laboratory assignment")
		}
		if a.WorkerID == nil || *a.WorkerID != s.userID || (a.Status != "accepted" && a.Status != "in_progress") {
			return 0, nil, errOf(409, "invalid_assignment_state", "assignment is not accepted by you")
		}
		var deadline time.Time
		db.QueryRow(`SELECT r.delivery_deadline FROM samples sm JOIN requests r ON r.id=sm.request_id WHERE sm.id=$1`, a.SampleID).Scan(&deadline)
		now := time.Now()
		if now.After(deadline) {
			db.Exec(`UPDATE samples SET status='expired' WHERE id=$1`, a.SampleID)
			audit(s.userID, s.activeRole, "confirm_laboratory_receipt", "sample", a.SampleID, false, M{"reason": "deadline_missed"})
			return 0, nil, errOf(409, "deadline_missed", "the delivery deadline has passed")
		}
		db.Exec(`UPDATE assignments SET status='completed', completed_at=now() WHERE id=$1`, a.ID)
		db.Exec(`UPDATE samples SET status='received', received_laboratory_id=$1, current_holder_id=$2 WHERE id=$3`, a.LaboratoryID, s.userID, a.SampleID)
		db.Exec(`UPDATE journeys SET status='completed' WHERE id=$1`, a.JourneyID)
		releaseJourneyCapacity(a.JourneyID)
		audit(s.userID, s.activeRole, "confirm_laboratory_receipt", "sample", a.SampleID, true, M{"laboratoryId": a.LaboratoryID})
		emitEvent("sample_received", "sample", a.SampleID, "", M{"sampleId": a.SampleID, "laboratoryId": a.LaboratoryID})
		return 201, M{"data": M{"sampleId": a.SampleID, "status": "received", "receivedAt": fmtTime(now)}}, nil
	})
}

func releaseJourneyCapacity(journeyID string) {
	// release reservations for all samples of the journey based on stored stops/conns
	// recompute the path from stops: connections between consecutive stop locations
	var stops []byte
	err := db.QueryRow(`SELECT stops FROM journeys WHERE id=$1`, journeyID).Scan(&stops)
	if err != nil {
		return
	}
	var stopList []M
	json.Unmarshal(stops, &stopList)
	var sampleCount int
	db.QueryRow(`SELECT count(*) FROM journey_samples WHERE journey_id=$1`, journeyID).Scan(&sampleCount)
	for i := 0; i < sampleCount; i++ {
		for j := 0; j+1 < len(stopList); j++ {
			from, _ := stopList[j]["locationId"].(string)
			to, _ := stopList[j+1]["locationId"].(string)
			db.Exec(`UPDATE connections SET reserved_units=GREATEST(0,reserved_units-1) WHERE from_location_id=$1 AND to_location_id=$2`, from, to)
			db.Exec(`UPDATE locations SET reserved_units=GREATEST(0,reserved_units-1) WHERE id=$1`, to)
		}
	}
}

