		audit(s.userID, s.activeRole, "confirm_laboratory_receipt", "sample", a.SampleID, true, M{"laboratoryId": a.LaboratoryID})
		emitEvent("sample_received", "sample", a.SampleID, "", M{"sampleId": a.SampleID, "laboratoryId": a.LaboratoryID})
		return 201, M{"data": M{"sampleId": a.SampleID, "status": "received", "receivedAt": fmtTime(now)}}, nil
	})
}

func releaseJourneyCapacity(journeyID string) {
	// release reservations for all samples of the journey based on stored stops/conns
	// recompute the path from stops: connections between consecutive stop locations
	var stops []byte
	err := db.QueryRow(`SELECT stops FROM journeys WHERE id=$1`, journeyID).Scan(&stops)
	if err != nil {
		return
	}
	var stopList []M
	json.Unmarshal(stops, &stopList)
	var sampleCount int
	db.QueryRow(`SELECT count(*) FROM journey_samples WHERE journey_id=$1`, journeyID).Scan(&sampleCount)
	for i := 0; i < sampleCount; i++ {
		for j := 0; j+1 < len(stopList); j++ {
			from, _ := stopList[j]["locationId"].(string)
			to, _ := stopList[j+1]["locationId"].(string)
			db.Exec(`UPDATE connections SET reserved_units=GREATEST(0,reserved_units-1) WHERE from_location_id=$1 AND to_location_id=$2`, from, to)
			db.Exec(`UPDATE locations SET reserved_units=GREATEST(0,reserved_units-1) WHERE id=$1`, to)
		}
	}
}

func handleRecordLabException(w http.ResponseWriter, r *http.Request) {
	s := requireAuth("record_laboratory_exception", true, w, r)
	if s == nil {
		return
	}
	var req struct {
		AssignmentID string `json:"assignmentId"`
		Reason       string `json:"reason"`
	}
	if e := decodeBody(r, &req); e != nil {
		writeAPIErr(w, e)
		return
	}
	a := loadAssignment(req.AssignmentID)
	if a == nil {
		writeErr(w, 404, "not_found", "assignment not found")
		return
	}
	if a.WorkerID == nil || *a.WorkerID != s.userID {
		writeErr(w, 403, "forbidden", "assignment is not yours")
		return
	}
	markSampleException(a.SampleID, "laboratory_exception", req.Reason)
	audit(s.userID, s.activeRole, "record_laboratory_exception", "sample", a.SampleID, true, M{"reason": req.Reason})
	writeData(w, 201, M{"sampleId": a.SampleID, "status": "exception", "reason": req.Reason})
}

