* { box-sizing: border-box; }
body { margin: 0; font-family: system-ui, -apple-system, sans-serif; background: #f4f6f8; color: #1c2733; }
header.topbar { display: flex; align-items: center; gap: 16px; background: #0d3b66; color: #fff; padding: 10px 20px; flex-wrap: wrap; }
header.topbar h1 { font-size: 18px; margin: 0; }
header.topbar nav { display: flex; gap: 6px; flex-wrap: wrap; }
header.topbar button { background: #155e9c; color: #fff; border: none; padding: 6px 12px; border-radius: 4px; cursor: pointer; }
header.topbar button.active { background: #fca311; color: #000; }
header.topbar .spacer { flex: 1; }
main { padding: 20px; max-width: 1400px; margin: 0 auto; }
.card { background: #fff; border: 1px solid #dde3ea; border-radius: 8px; padding: 16px; margin-bottom: 16px; }
.card h2, .card h3 { margin-top: 0; }
label { display: block; margin: 8px 0 2px; font-size: 13px; font-weight: 600; }
input, select, textarea { width: 100%; padding: 7px; border: 1px solid #b9c4cf; border-radius: 4px; font-size: 14px; }
button.primary { background: #0d3b66; color: #fff; border: none; padding: 8px 16px; border-radius: 4px; cursor: pointer; margin-top: 10px; }
button.small { background: #155e9c; color: #fff; border: none; padding: 4px 10px; border-radius: 4px; cursor: pointer; margin: 2px; font-size: 12px; }
button.danger { background: #b3261e; }
.error-box { background: #fdecea; border: 1px solid #f5c6c0; color: #8c1d18; padding: 10px; border-radius: 4px; margin: 10px 0; }
