import { useEffect, useRef } from 'react'
import maplibregl from 'maplibre-gl'
import 'maplibre-gl/dist/maplibre-gl.css'
import * as pmtiles from 'pmtiles'

export interface MapMarker {
  id: string
  latitude: number
  longitude: number
  color?: string
  label?: string
}

const protocol = new pmtiles.Protocol()
maplibregl.addProtocol('pmtiles', protocol.tile)

export default function MapView({ markers }: { markers: MapMarker[] }) {
  const ref = useRef<HTMLDivElement>(null)
  const mapRef = useRef<maplibregl.Map | null>(null)
  const markersRef = useRef<maplibregl.Marker[]>([])

  useEffect(() => {
    if (!ref.current || mapRef.current) return
    const map = new maplibregl.Map({
      container: ref.current,
      style: {
        version: 8,
        sources: {
          local: {
            type: 'vector',
            url: 'pmtiles:///map-assets/bangalore.pmtiles',
          },
        },
        layers: [
          { id: 'background', type: 'background', paint: { 'background-color': '#e8eef2' } },
        ],
      },
      center: [77.5946, 12.9716],
      zoom: 11,
    })
    map.addControl(new maplibregl.NavigationControl())
    map.on('load', () => {
      const tryLayer = (id: string, sourceLayer: string, type: string, paint: any, filter?: any) => {
        try {
          map.addLayer({ id, type: type as any, source: 'local', 'source-layer': sourceLayer, paint, ...(filter ? { filter } : {}) })
        } catch {
          /* source layer not present in tiles */
        }
      }
      tryLayer('land', 'landuse', 'fill', { 'fill-color': '#eef4ea' })
      tryLayer('water', 'water', 'fill', { 'fill-color': '#b3d1f0' })
      tryLayer('roads', 'roads', 'line', { 'line-color': '#ffffff', 'line-width': 1.5 })
      tryLayer('transportation', 'transportation', 'line', { 'line-color': '#ffffff', 'line-width': 1.5 })
      tryLayer('buildings', 'buildings', 'fill', { 'fill-color': '#dcd6cd' })
      tryLayer('building', 'building', 'fill', { 'fill-color': '#dcd6cd' })
    })
    mapRef.current = map
    return () => {
      map.remove()
      mapRef.current = null
    }
  }, [])

  useEffect(() => {
    const map = mapRef.current
    if (!map) return
    markersRef.current.forEach((m) => m.remove())
    markersRef.current = markers.map((mk) => {
      const el = document.createElement('div')
      el.style.width = '14px'
      el.style.height = '14px'
      el.style.borderRadius = '50%'
      el.style.background = mk.color || '#0d3b66'
      el.style.border = '2px solid #fff'
      el.title = mk.label || mk.id
      return new maplibregl.Marker({ element: el }).setLngLat([mk.longitude, mk.latitude]).addTo(map)
    })
  }, [JSON.stringify(markers)])

  return <div className="map-container" ref={ref} aria-label="Network map" />
}

