import { useCallback, useEffect, useState } from 'react'
import { api, errText, getToken, setToken } from './api'
import MapView, { MapMarker } from './MapView'

const uuid = () => (crypto as any).randomUUID()
const now = () => new Date().toISOString()

const ROLE_LABELS: Record<string, string> = {
  administrator: 'Administrator',
  dispatcher: 'Dispatcher',
  requester: 'Requester',
  collection_professional: 'Collection Professional',
  delivery_partner: 'Relay Courier',
  node_handler: 'Node Handler',
  laboratory_team: 'Laboratory Intake',
}

function Field({ label, children }: { label: string; children: any }) {
  return (
    <div>
      <label>{label}</label>
      {children}
    </div>
  )
}

function ErrorBox({ err }: { err: string | null }) {
  if (!err) return null
  return (
    <div className="error-box" role="alert">
      {err}
    </div>
  )
}

export default function App() {
  const [user, setUser] = useState<any>(null)
  const [bootError, setBootError] = useState<string | null>(null)
  const [loading, setLoading] = useState(true)

  const loadBootstrap = useCallback(async () => {
    if (!getToken()) {
      setLoading(false)
      return
    }
    try {
      const data = await api('ui-bootstrap')
      setUser(data.user)
    } catch (e) {
      setToken(null)
      setUser(null)
      setBootError(errText(e))
    } finally {
      setLoading(false)
    }
  }, [])

  useEffect(() => {
    loadBootstrap()
  }, [loadBootstrap])

  if (loading) return <main>Loading…</main>
  if (!user) return <Login onLogin={loadBootstrap} bootError={bootError} />
  if (user.roleSelectionRequired || !user.activeRole)
    return <RoleSelect user={user} onSelected={loadBootstrap} />
  return <Shell user={user} onUserChange={loadBootstrap} onSignOut={() => { setUser(null) }} />
}

function Login({ onLogin, bootError }: { onLogin: () => void; bootError: string | null }) {
  const [username, setUsername] = useState('')
  const [password, setPassword] = useState('')
  const [err, setErr] = useState<string | null>(bootError)
  const submit = async (e: any) => {
    e.preventDefault()
    setErr(null)
    try {
      const data = await api('authenticate', { username, password })
      setToken(data.sessionToken)
      onLogin()
    } catch (e2) {
      setErr(errText(e2))
    }
  }
  return (
    <main>
      <div className="login-wrap card">
        <h2>Sign in — Lab Sample Pickup &amp; Delivery</h2>
        <ErrorBox err={err} />
        <form onSubmit={submit}>
          <Field label="Username">
            <input aria-label="Username" value={username} onChange={(e) => setUsername(e.target.value)} autoComplete="username" />
          </Field>
          <Field label="Password">
            <input aria-label="Password" type="password" value={password} onChange={(e) => setPassword(e.target.value)} autoComplete="current-password" />
          </Field>
          <button className="primary" type="submit">
            Sign in
          </button>
        </form>
      </div>
    </main>
  )
}

function RoleSelect({ user, onSelected }: { user: any; onSelected: () => void }) {
  const [err, setErr] = useState<string | null>(null)
  const pick = async (role: string) => {
    setErr(null)
    try {
      await api('select-active-role', { role })
      onSelected()
    } catch (e) {
      setErr(errText(e))
    }
  }
  return (
    <main>
      <div className="login-wrap card">
        <h2>Select your working role</h2>
        <p>You hold multiple roles. Choose the role you are currently working under.</p>
        <ErrorBox err={err} />
        {user.roles.map((r: string) => (
          <button key={r} className="primary" style={{ display: 'block', width: '100%' }} onClick={() => pick(r)} aria-label={`Switch role to ${ROLE_LABELS[r] || r}`}>
            {ROLE_LABELS[r] || r}
          </button>
        ))}
      </div>
    </main>
  )
}

function Shell({ user, onUserChange, onSignOut }: { user: any; onUserChange: () => void; onSignOut: () => void }) {
  const role: string = user.activeRole
  const isWorker = ['collection_professional', 'delivery_partner', 'node_handler', 'laboratory_team'].includes(role)
  const isDispatch = ['dispatcher', 'administrator'].includes(role)
  const tabs: string[] = []
  if (role === 'requester') tabs.push('My Requests', 'New Request', 'Serviceability Check')
  if (isWorker) tabs.push('My Work', 'Register Pre-sealed Sample')
  if (isDispatch) tabs.push('Monitor', 'My Work', 'Audit Trail')
  if (role === 'administrator') tabs.push('Administration')
  tabs.push('Map')
  const [tab, setTab] = useState(tabs[0])
  const [refreshTick, setRefreshTick] = useState(0)
  const refresh = () => setRefreshTick((t) => t + 1)

  useEffect(() => {
    let ws: WebSocket | null = null
    try {
      const proto = location.protocol === 'https:' ? 'wss' : 'ws'
      ws = new WebSocket(`${proto}://${location.host}/api/events`, [`bearer.${getToken()}`])
      ws.onmessage = () => refresh()
    } catch {
      /* realtime optional */
    }
    return () => ws?.close()
  }, [])

  const switchRole = async (r: string) => {
    await api('select-active-role', { role: r })
    onUserChange()
  }
  const signOut = async () => {
    try {
      await api('sign-out', {})
    } catch {
      /* ignore */
    }
    setToken(null)
    onSignOut()
  }

  return (
    <>
      <header className="topbar">
        <h1>Lab Sample Pickup &amp; Delivery</h1>
        <nav>
          {tabs.map((t) => (
            <button key={t} className={t === tab ? 'active' : ''} onClick={() => setTab(t)}>
              {t}
            </button>
          ))}
        </nav>
        <span className="spacer" />
        <span>
          {user.fullName || user.username} — {ROLE_LABELS[role] || role}
        </span>
        {user.roles.length > 1 && (
          <select aria-label="Switch role" value={role} onChange={(e) => switchRole(e.target.value)} style={{ width: 'auto' }}>
            {user.roles.map((r: string) => (
              <option key={r} value={r}>
                {ROLE_LABELS[r] || r}
              </option>
            ))}
          </select>
        )}
        <button onClick={signOut} aria-label="Sign out">
          Sign out
        </button>
      </header>
      <main key={refreshTick}>
        {tab === 'My Requests' && <RequesterSamples />}
        {tab === 'New Request' && <NewRequest onCreated={refresh} />}
        {tab === 'Serviceability Check' && <ServiceabilityCheck />}
        {tab === 'My Work' && <WorkView role={role} onChanged={refresh} />}
        {tab === 'Register Pre-sealed Sample' && <PresealedForm onCreated={refresh} />}
        {tab === 'Monitor' && <Monitor />}
        {tab === 'Audit Trail' && <AuditView />}
        {tab === 'Administration' && <AdminView onChanged={refresh} />}
        {tab === 'Map' && <MapTab role={role} />}
      </main>
    </>
  )
}

/* ----------------------------- shared pieces ----------------------------- */

function SampleDetail({ sampleId }: { sampleId: string }) {
  const [state, setState] = useState<any>(null)
  const [life, setLife] = useState<any>(null)
  const [plan, setPlan] = useState<any>(null)
  const [err, setErr] = useState<string | null>(null)
  useEffect(() => {
    ;(async () => {
      try {
        setState(await api('read-sample-state', { sampleId }))
        setLife(await api('read-sample-lifecycle', { sampleId }))
      } catch (e) {
        setErr(errText(e))
      }
    })()
  }, [sampleId])
  if (err) return <ErrorBox err={err} />
  if (!state || !life) return <p>Loading sample…</p>
  const timeline = [...(state.timeline || [])].sort((a, b) => a.eventId - b.eventId)
  const loadPlan = async () => {
    try {
      setPlan(await api('read-journey-plan', { journeyId: state.activeJourneyId || life.activeJourneyId }))
    } catch (e) {
      setErr(errText(e))
    }
  }
  return (
    <div className="card">
      <h3>Sample {sampleId}</h3>
      <p>
        Status: <span className={`badge ${life.status}`}>{life.status}</span>{' '}
        {life.exception && <span className="badge exception">Exception: {life.exception.reason || life.exception.type || 'flagged'}</span>}{' '}
        {state.locationStale ? <span className="badge stale">Location stale</span> : <span className="badge ok">Location fresh</span>}
      </p>
      <p>
        Sealed: {String(life.sealed)} · Current holder: <span className="mono">{life.currentHolderId || '—'}</span> · Deadline: {state.deliveryDeadline}
      </p>
      {state.latestLocation && (
        <p>
          Last known location: {state.latestLocation.latitude}, {state.latestLocation.longitude} at {state.locationRecordedAt}
        </p>
      )}
      {(state.activeJourneyId || life.activeJourneyId) && (
        <button className="small" onClick={loadPlan}>
          View journey plan
        </button>
      )}
      {plan && (
        <details open>
          <summary>Journey plan (v{plan.planVersion})</summary>
          <pre>{JSON.stringify(plan, null, 2)}</pre>
        </details>
      )}
      <h4>Status history</h4>
      <ol className="timeline" aria-label="Status history">
        {timeline.map((t: any) => (
          <li key={t.eventId} className={t.success ? '' : 'fail'}>
            <strong>{t.action}</strong> — {t.occurredAt} · role {t.role || '—'} · {t.success ? 'ok' : 'failed'}
            {t.details && Object.keys(t.details).length > 0 && <div className="mono">{JSON.stringify(t.details)}</div>}
          </li>
        ))}
      </ol>
    </div>
  )
}

/* ------------------------------- requester ------------------------------- */

function RequesterSamples() {
  const [work, setWork] = useState<any>(null)
  const [err, setErr] = useState<string | null>(null)
  const [selected, setSelected] = useState<string | null>(null)
  useEffect(() => {
    api('list-role-work', { role: 'requester', status: 'all' })
      .then(setWork)
      .catch((e) => setErr(errText(e)))
  }, [])
  if (err) return <ErrorBox err={err} />
  if (!work) return <p>Loading…</p>
  const groups: [string, any[]][] = [
    ['In progress', work.inProgress],
    ['Pending', work.pending],
    ['Completed', work.completed],
  ]
  return (
    <>
      {groups.map(([name, items]) => (
        <div className="card" key={name}>
          <h3>{name} requests</h3>
          {items.length === 0 && <p>None.</p>}
          {items.length > 0 && (
            <table>
              <thead>
                <tr>
                  <th>Sample</th>
                  <th>Status</th>
                  <th>Deadline</th>
                  <th></th>
                </tr>
              </thead>
              <tbody>
                {items.map((it: any) => (
                  <tr key={it.sampleId || it.journeyId}>
                    <td className="mono">{it.sampleId || it.journeyId}</td>
                    <td>
                      <span className={`badge ${it.status}`}>{it.status}</span>
                    </td>
                    <td>{it.deliveryDeadline || '—'}</td>
                    <td>{it.sampleId && <button className="small" onClick={() => setSelected(it.sampleId)}>Track</button>}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      ))}
      {selected && <SampleDetail sampleId={selected} />}
    </>
  )
}

function SampleTypeSelect({ value, onChange, types }: { value: string; onChange: (v: string) => void; types: any[] }) {
  return (
    <select aria-label="Sample type" value={value} onChange={(e) => onChange(e.target.value)}>
      <option value="">Select sample type…</option>
      {types.map((t) => (
        <option key={t.sampleTypeId} value={t.sampleTypeId}>
          {t.name}
        </option>
      ))}
    </select>
  )
}

function useSampleTypes() {
  const [types, setTypes] = useState<any[]>([])
  useEffect(() => {
    api('list-sample-types')
      .then((d) => setTypes(d.sampleTypes || []))
      .catch(() => setTypes([]))
  }, [])
  return types
}

function RequestFormFields({ form, setForm, types }: { form: any; setForm: any; types: any[] }) {
  const set = (k: string, v: any) => setForm({ ...form, [k]: v })
  return (
    <>
      <Field label="Origin type">
        <select aria-label="Origin type" value={form.originType} onChange={(e) => set('originType', e.target.value)}>
          <option value="home">Home</option>
          <option value="clinic">Clinic</option>
          <option value="node">Network node</option>
        </select>
      </Field>
      <Field label="Origin latitude">
        <input aria-label="Origin latitude" type="number" step="any" value={form.lat} onChange={(e) => set('lat', e.target.value)} />
      </Field>
      <Field label="Origin longitude">
        <input aria-label="Origin longitude" type="number" step="any" value={form.lon} onChange={(e) => set('lon', e.target.value)} />
      </Field>
      <Field label="Sample type">
        <SampleTypeSelect value={form.sampleTypeId} onChange={(v) => set('sampleTypeId', v)} types={types} />
      </Field>
      <Field label="Earliest collection time">
        <input aria-label="Earliest collection time" type="datetime-local" value={form.earliest} onChange={(e) => set('earliest', e.target.value)} />
      </Field>
      <Field label="Latest collection time">
        <input aria-label="Latest collection time" type="datetime-local" value={form.latest} onChange={(e) => set('latest', e.target.value)} />
      </Field>
      <Field label="Delivery deadline">
        <input aria-label="Delivery deadline" type="datetime-local" value={form.deadline} onChange={(e) => set('deadline', e.target.value)} />
      </Field>
    </>
  )
}

const toISO = (v: string) => (v ? new Date(v).toISOString() : '')

function NewRequest({ onCreated }: { onCreated: () => void }) {
  const types = useSampleTypes()
  const [form, setForm] = useState({ originType: 'home', lat: '12.9716', lon: '77.5946', sampleTypeId: '', earliest: '', latest: '', deadline: '' })
  const [err, setErr] = useState<string | null>(null)
  const [result, setResult] = useState<any>(null)
  const submit = async (e: any) => {
    e.preventDefault()
    setErr(null)
    setResult(null)
    if (!form.sampleTypeId) {
      setErr('Please select a sample type.')
      return
    }
    if (!form.earliest || !form.latest || !form.deadline) {
      setErr('Collection window and delivery deadline are required.')
      return
    }
    try {
      const data = await api('create-collection-request', {
        origin: { latitude: parseFloat(form.lat), longitude: parseFloat(form.lon) },
        originType: form.originType,
        requestedAt: now(),
        deliveryDeadline: toISO(form.deadline),
        earliestCollectionAt: toISO(form.earliest),
        latestCollectionAt: toISO(form.latest),
        sampleTypeId: form.sampleTypeId,
        idempotencyKey: uuid(),
      })
      setResult(data)
      onCreated()
    } catch (e2) {
      setErr(errText(e2))
    }
  }
  return (
    <div className="card">
      <h2>New collection request</h2>
      <ErrorBox err={err} />
      {result && (
        <div className="info-box">
          Request created. Sample <span className="mono">{result.sampleId}</span> — serviceability: {result.serviceability}
          {result.serviceabilityReason ? ` (${result.serviceabilityReason})` : ''}
        </div>
      )}
      <form onSubmit={submit}>
        <RequestFormFields form={form} setForm={setForm} types={types} />
        <button className="primary" type="submit">
          Create request
        </button>
      </form>
    </div>
  )
}

function ServiceabilityCheck() {
  const types = useSampleTypes()
  const [form, setForm] = useState({ originType: 'home', lat: '12.9716', lon: '77.5946', sampleTypeId: '', earliest: '', latest: '', deadline: '' })
  const [err, setErr] = useState<string | null>(null)
  const [result, setResult] = useState<any>(null)
  const submit = async (e: any) => {
    e.preventDefault()
    setErr(null)
    setResult(null)
    try {
      const data = await api('check-serviceability', {
        origin: { latitude: parseFloat(form.lat), longitude: parseFloat(form.lon) },
        originType: form.originType,
        deliveryDeadline: toISO(form.deadline) || now(),
        earliestCollectionAt: toISO(form.earliest) || now(),
        latestCollectionAt: toISO(form.latest) || now(),
        sampleTypeId: form.sampleTypeId,
      })
      setResult(data)
    } catch (e2) {
      setErr(errText(e2))
    }
  }
  return (
    <div className="card">
      <h2>Serviceability check (dry run)</h2>
      <p>This check does not create a request, sample, journey, assignment or capacity reservation.</p>
      <ErrorBox err={err} />
      {result && (
        <div className="info-box" aria-label="Serviceability result">
          {result.serviceable ? 'Serviceable' : `Not serviceable: ${result.reason}`} (calculation version {result.serviceabilityVersion})
          {result.targetLaboratoryId && <div>Target laboratory: <span className="mono">{result.targetLaboratoryId}</span></div>}
          {result.estimatedArrivalAt && <div>Estimated arrival: {result.estimatedArrivalAt}</div>}
        </div>
      )}
      <form onSubmit={submit}>
        <RequestFormFields form={form} setForm={setForm} types={types} />
        <button className="primary" type="submit">
          Check serviceability
        </button>
      </form>
    </div>
  )
}

/* -------------------------------- workers -------------------------------- */

function WorkView({ role, onChanged }: { role: string; onChanged: () => void }) {
  const [work, setWork] = useState<any>(null)
  const [err, setErr] = useState<string | null>(null)
  const [tab, setTab] = useState('pending')
  const [selected, setSelected] = useState<string | null>(null)
  const load = useCallback(() => {
    api('list-role-work', { role, status: 'all' })
      .then(setWork)
      .catch((e) => setErr(errText(e)))
  }, [role])
  useEffect(load, [load])
  const act = async (path: string, body: any) => {
    setErr(null)
    try {
      await api(path, body)
      load()
      onChanged()
    } catch (e) {
      setErr(errText(e))
    }
  }
  if (!work) return <p>Loading…</p>
  const items = work[tab === 'pending' ? 'pending' : tab === 'inProgress' ? 'inProgress' : 'completed'] || []
  return (
    <>
      <ErrorBox err={err} />
      <div className="tabs">
        <button className={tab === 'pending' ? 'active' : ''} onClick={() => setTab('pending')}>
          Pending ({work.pending.length})
        </button>
        <button className={tab === 'inProgress' ? 'active' : ''} onClick={() => setTab('inProgress')}>
          In progress ({work.inProgress.length})
        </button>
        <button className={tab === 'completed' ? 'active' : ''} onClick={() => setTab('completed')}>
          Completed ({work.completed.length})
        </button>
      </div>
      <div className="card">
        <table>
          <thead>
            <tr>
              <th>Kind</th>
              <th>ID</th>
              <th>Status</th>
              <th>Sample</th>
              <th>Details</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            {items.map((it: any) => (
              <WorkRow key={it.assignmentId || it.sampleId || it.journeyId} it={it} tab={tab} act={act} onTrack={setSelected} />
            ))}
            {items.length === 0 && (
              <tr>
                <td colSpan={6}>No work in this bucket.</td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
      {selected && <SampleDetail sampleId={selected} />}
    </>
  )
}

function WorkRow({ it, tab, act, onTrack }: { it: any; tab: string; act: any; onTrack: (id: string) => void }) {
  const id = it.assignmentId || it.sampleId || it.journeyId
  const [lat, setLat] = useState('12.9716')
  const [lon, setLon] = useState('77.5946')
  const [temp, setTemp] = useState('4')
  const [container, setContainer] = useState('standard')
  const [handoffId, setHandoffId] = useState('')
  const [receiverId, setReceiverId] = useState('')
  const [toAssignmentId, setToAssignmentId] = useState('')
  const [reason, setReason] = useState('')
  const [cap, setCap] = useState('')
  const [cooledCap, setCooledCap] = useState('')
  const sampleId = it.sampleId
  const assignmentId = it.assignmentId
  return (
    <tr>
      <td>{it.kind || 'sample'}</td>
      <td className="mono">{id}</td>
      <td>
        <span className={`badge ${it.status}`}>{it.status}</span>
        {it.offerExpiresAt && <div className="mono">offer expires {it.offerExpiresAt}</div>}
      </td>
      <td className="mono">{sampleId || (it.sampleIds || []).join(', ') || '—'}</td>
      <td className="mono" style={{ maxWidth: 260, wordBreak: 'break-all' }}>
        {it.fromLocationId ? `from ${it.fromLocationId} ` : ''}
        {it.toLocationId ? `to ${it.toLocationId}` : ''}
        {it.nodeId ? `node ${it.nodeId}` : ''}
        {it.laboratoryId ? `lab ${it.laboratoryId}` : ''}
        {it.deliveryDeadline ? `deadline ${it.deliveryDeadline}` : ''}
      </td>
      <td style={{ minWidth: 280 }}>
        {tab === 'pending' && assignmentId && (
          <>
            <button className="small" onClick={() => act('accept-assignment', { assignmentId })} aria-label="Accept assignment">
              Accept
            </button>
            <button className="small danger" onClick={() => act('decline-assignment', { assignmentId })} aria-label="Decline assignment">
              Decline
            </button>
          </>
        )}
