function PresealedForm({ onCreated }: { onCreated: () => void }) {
  const types = useSampleTypes()
  const [form, setForm] = useState({ lat: '12.9716', lon: '77.5946', sampleTypeId: '', deadline: '', requesterId: '', originNodeId: '' })
  const [err, setErr] = useState<string | null>(null)
  const [result, setResult] = useState<any>(null)
  const submit = async (e: any) => {
    e.preventDefault()
    setErr(null)
    try {
      const t = types.find((x) => x.sampleTypeId === form.sampleTypeId)
      const data = await api('ingest-presealed-sample', {
        requesterId: form.requesterId || undefined,
        origin: { latitude: parseFloat(form.lat), longitude: parseFloat(form.lon) },
        originType: form.originNodeId ? 'node' : 'clinic',
        originNodeId: form.originNodeId || undefined,
        requestedAt: now(),
        deliveryDeadline: toISO(form.deadline),
        sampleTypeId: form.sampleTypeId,
        containerType: t?.containerType || 'standard',
        temperatureMinC: t?.temperatureMinC ?? -80,
        temperatureMaxC: t?.temperatureMaxC ?? 30,
        idempotencyKey: uuid(),
      })
      setResult(data)
      onCreated()
    } catch (e2) {
