            </button>
            <button className="small danger" onClick={() => act('decline-assignment', { assignmentId })} aria-label="Decline assignment">
              Decline
            </button>
          </>
        )}
        {tab === 'inProgress' && it.kind === 'collection' && (
          <button
            className="small"
            onClick={() =>
              act('collect-and-seal-sample', { sampleId, assignmentId, collectedAt: now(), containerType: container, observedTemperatureC: parseFloat(temp), idempotencyKey: uuid() })
            }
