          </button>
        )}
        {tab === 'inProgress' && assignmentId && (it.kind === 'collection' || it.kind === 'transport') && (
          <span>
            <input style={{ width: 80 }} aria-label="Latitude" value={lat} onChange={(e) => setLat(e.target.value)} />
            <input style={{ width: 80 }} aria-label="Longitude" value={lon} onChange={(e) => setLon(e.target.value)} />
            <button
              className="small"
              onClick={() => act('record-worker-location', { assignmentId, coordinate: { latitude: parseFloat(lat), longitude: parseFloat(lon) }, sequence: 1, recordedAt: now() })}
            >
