            </button>
          </span>
        )}
        {tab === 'inProgress' && assignmentId && sampleId && (
          <span>
            <input style={{ width: 90 }} aria-label="Container type" value={container} onChange={(e) => setContainer(e.target.value)} />
            <input style={{ width: 60 }} aria-label="Observed temperature" value={temp} onChange={(e) => setTemp(e.target.value)} />
            <button
              className="small"
              onClick={() =>
                act('record-handling-checkpoint', { sampleId, assignmentId, containerType: container, observedTemperatureC: parseFloat(temp), recordedAt: now(), idempotencyKey: uuid() })
              }
