              Checkpoint
            </button>
          </span>
        )}
        {tab === 'inProgress' && assignmentId && sampleId && (
          <span>
            <input style={{ width: 110 }} placeholder="receiver user id" aria-label="Receiver" value={receiverId} onChange={(e) => setReceiverId(e.target.value)} />
