              className="small"
              onClick={() =>
                act('initiate-handoff', { sampleId, fromAssignmentId: assignmentId, toAssignmentId, receiverId, initiatedAt: now(), idempotencyKey: uuid() })
              }
            >
              Initiate handoff
            </button>
          </span>
        )}
        {tab === 'inProgress' && it.kind === 'laboratory' && (
          <span>
            <button
              className="small"
              onClick={() => act('confirm-laboratory-receipt', { sampleId, laboratoryId: it.laboratoryId, assignmentId, receivedAt: now(), idempotencyKey: uuid() })}
            >
              Confirm receipt
            </button>
            <input style={{ width: 110 }} placeholder="exception reason" aria-label="Exception reason" value={reason} onChange={(e) => setReason(e.target.value)} />
            <button
              className="small danger"
