          <span>
            <input style={{ width: 60 }} placeholder="reg" aria-label="Regular capacity" value={cap} onChange={(e) => setCap(e.target.value)} />
            <input style={{ width: 60 }} placeholder="cooled" aria-label="Cooled capacity" value={cooledCap} onChange={(e) => setCooledCap(e.target.value)} />
            <button
              className="small"
              onClick={() =>
                act('configure-capacity', {
