// ---- list role work ----

func assignmentWorkItem(a *assignmentRow) M {
	m := M{
		"kind": a.Kind, "assignmentId": a.ID, "sampleId": a.SampleID,
		"status": a.Status, "journeyId": a.JourneyID, "sequence": a.Sequence,
		"history": timelineForSample(a.SampleID),
	}
	if a.FromLocationID != nil {
		m["fromLocationId"] = *a.FromLocationID
	}
	if a.ToLocationID != nil {
		m["toLocationId"] = *a.ToLocationID
	}
	if a.NodeID != nil {
		m["nodeId"] = *a.NodeID
	}
	if a.LaboratoryID != nil {
		m["laboratoryId"] = *a.LaboratoryID
		m["destinationCapacity"] = locationJSON(*a.LaboratoryID)["capacity"]
	}
	if a.OfferExpiresAt != nil {
		m["offerExpiresAt"] = fmtTime(*a.OfferExpiresAt)
	}
	return m
}

func sampleWorkItem(sampleID string) M {
	var reqID, status, serviceability string
	var requestedAt, deadline time.Time
	var earliest, latest *time.Time
	var journeyID, labID, holder, requesterID *string
	var recAt *time.Time
	err := db.QueryRow(`SELECT s.request_id, s.status, r.serviceability, r.requested_at, r.delivery_deadline, r.earliest_collection_at, r.latest_collection_at, s.active_journey_id, s.target_laboratory_id, s.current_holder_id, r.requester_id, s.location_recorded_at
		FROM samples s JOIN requests r ON r.id=s.request_id WHERE s.id=$1`, sampleID).
		Scan(&reqID, &status, &serviceability, &requestedAt, &deadline, &earliest, &latest, &journeyID, &labID, &holder, &requesterID, &recAt)
	if err != nil {
		return nil
	}
	m := M{
		"kind": "sample", "sampleId": sampleID, "requestId": reqID, "status": status,
		"serviceability": serviceability, "requestedAt": fmtTime(requestedAt),
		"deliveryDeadline": fmtTime(deadline),
		"history":          timelineForSample(sampleID),
		"locationStale":    isStale(recAt),
	}
	if earliest != nil {
		m["earliestCollectionAt"] = fmtTime(*earliest)
	}
	if latest != nil {
		m["latestCollectionAt"] = fmtTime(*latest)
	}
	if journeyID != nil {
		m["journeyId"] = *journeyID
		m["activeJourneyId"] = *journeyID
	}
	if labID != nil {
		m["laboratoryId"] = *labID
	}
	if holder != nil {
		m["currentHolderId"] = *holder
	}
	if requesterID != nil {
		m["requesterId"] = *requesterID
	}
	if recAt != nil {
		m["locationRecordedAt"] = fmtTime(*recAt)
	}
	return m
}

func journeyWorkItem(j *journeyRow) M {
	var count int
	db.QueryRow(`SELECT count(*) FROM assignments WHERE journey_id=$1`, j.ID).Scan(&count)
	m := M{
		"kind": "journey", "journeyId": j.ID, "status": j.Status, "routeMode": j.RouteMode,
		"planVersion": j.PlanVersion, "sampleIds": journeySampleIDs(j.ID),
		"assignmentCount": count, "history": []M{},
	}
	if j.EstimatedAt != nil {
		m["estimatedDeliveryAt"] = fmtTime(*j.EstimatedAt)
	} else {
		m["estimatedDeliveryAt"] = nil
	}
	return m
}

func handleListRoleWork(w http.ResponseWriter, r *http.Request) {
	s := requireAuth("list_role_work", true, w, r)
	if s == nil {
		return
	}
	var req struct {
		Role string `json:"role"`
	}
	if e := decodeBody(r, &req); e != nil {
		writeAPIErr(w, e)
		return
	}
	if !validRoles[req.Role] {
		writeErr(w, 400, "invalid_role", "unknown role")
		return
	}
	held := false
	for _, ur := range s.roles {
		if ur == req.Role {
			held = true
		}
	}
	if !held {
		writeErr(w, 403, "role_not_held", "role is not assigned to this user")
		return
	}
	pending := []M{}
	inProgress := []M{}
	completed := []M{}
	switch req.Role {
	case "requester":
		rows, _ := db.Query(`SELECT s.id, s.status FROM samples s JOIN requests r ON r.id=s.request_id WHERE r.requester_id=$1 ORDER BY s.created_at`, s.userID)
		var items []struct{ id, status string }
		for rows != nil && rows.Next() {
			var it struct{ id, status string }
			rows.Scan(&it.id, &it.status)
			items = append(items, it)
		}
		if rows != nil {
			rows.Close()
		}
		for _, it := range items {
			m := sampleWorkItem(it.id)
			switch it.status {
			case "received", "cancelled", "expired":
				completed = append(completed, m)
			case "requested", "awaiting_collection":
				pending = append(pending, m)
			default:
				inProgress = append(inProgress, m)
			}
		}
	case "dispatcher", "administrator":
		rows, _ := db.Query(`SELECT id, status FROM journeys ORDER BY created_at DESC LIMIT 200`)
		var js []struct{ id, status string }
		for rows != nil && rows.Next() {
			var it struct{ id, status string }
			rows.Scan(&it.id, &it.status)
			js = append(js, it)
		}
		if rows != nil {
			rows.Close()
		}
		for _, it := range js {
			j := loadJourney(it.id)
			m := journeyWorkItem(j)
			switch it.status {
			case "completed", "cancelled", "expired":
				completed = append(completed, m)
			case "planned":
				pending = append(pending, m)
			default:
				inProgress = append(inProgress, m)
			}
		}
	default:
		// worker roles
		rows, _ := db.Query(`SELECT id, status FROM assignments WHERE offered_to=$1 OR worker_id=$1 ORDER BY created_at DESC LIMIT 300`, s.userID)
		var as []struct{ id, status string }
		for rows != nil && rows.Next() {
			var it struct{ id, status string }
			rows.Scan(&it.id, &it.status)
			as = append(as, it)
		}
		if rows != nil {
			rows.Close()
		}
		for _, it := range as {
			a := loadAssignment(it.id)
			if a == nil {
				continue
			}
			m := assignmentWorkItem(a)
			switch a.Status {
			case "offered":
				if a.OfferedTo != nil && *a.OfferedTo == s.userID {
					pending = append(pending, m)
				}
			case "accepted", "in_progress":
				if a.WorkerID != nil && *a.WorkerID == s.userID {
					inProgress = append(inProgress, m)
				}
			case "completed":
				if a.WorkerID != nil && *a.WorkerID == s.userID {
					completed = append(completed, m)
				}
			}
		}
	}
	audit(s.userID, s.activeRole, "list_role_work", "user", s.userID, true, M{"role": req.Role})
	writeData(w, 200, M{"pending": pending, "inProgress": inProgress, "completed": completed})
}

// ---- journey plan read ----

func journeyPlanJSON(j *journeyRow, viewer *sessionInfo) M {
	sampleIDs := journeySampleIDs(j.ID)
	assignments := journeyAssignments(j.ID)
	legs := []M{}
	assignedWorkers := map[string]bool{}
	var collectionIDs, nodeIDs, labIDs []string
	var firstT, midT, finalT string
	transportIdx := 0
	transportTotal := 0
	for _, a := range assignments {
		if a.Kind == "transport" {
			transportTotal++
		}
	}
	for _, a := range assignments {
		leg := M{"assignmentId": a.ID, "sequence": a.Sequence, "status": a.Status}
		if a.FromLocationID != nil {
			leg["fromLocationId"] = *a.FromLocationID
		}
		if a.ToLocationID != nil {
			leg["toLocationId"] = *a.ToLocationID
		}
		if a.WorkerID != nil {
			leg["workerId"] = *a.WorkerID
			assignedWorkers[*a.WorkerID] = true
		}
		leg["sampleId"] = a.SampleID
		legs = append(legs, leg)
		switch a.Kind {
		case "collection":
			collectionIDs = append(collectionIDs, a.ID)
		case "node":
			nodeIDs = append(nodeIDs, a.ID)
		case "laboratory":
			labIDs = append(labIDs, a.ID)
		case "transport":
			transportIdx++
			if transportIdx == 1 {
				firstT = a.ID
			}
			if transportTotal > 2 && transportIdx == transportTotal-1 {
				midT = a.ID
			}
			if transportIdx == transportTotal {
				finalT = a.ID
			}
		}
	}
	workerIDs := []string{}
	for wid := range assignedWorkers {
		workerIDs = append(workerIDs, wid)
	}
	if collectionIDs == nil {
		collectionIDs = []string{}
	}
	if nodeIDs == nil {
		nodeIDs = []string{}
	}
	if labIDs == nil {
		labIDs = []string{}
	}
	// worker view: only own legs
	if viewer.activeRole != "dispatcher" && viewer.activeRole != "administrator" && viewer.activeRole != "requester" {
		ownLegs := []M{}
		ownIDs := []string{}
		for i, a := range assignments {
			own := (a.WorkerID != nil && *a.WorkerID == viewer.userID) || (a.OfferedTo != nil && *a.OfferedTo == viewer.userID)
			if own {
				ownLegs = append(ownLegs, legs[i])
				ownIDs = append(ownIDs, a.ID)
			}
		}
		m := M{
			"journeyId": j.ID, "planVersion": j.PlanVersion, "routeMode": j.RouteMode,
			"status": j.Status, "scope": "assigned_legs",
			"assignmentIds": ownIDs, "legs": ownLegs, "orderedStops": j.Stops,
			"sampleIds": sampleIDs,
			"collectionAssignmentIds": collectionIDs, "nodeAssignmentIds": nodeIDs,
			"laboratoryAssignmentIds": labIDs, "assignedWorkerIds": workerIDs,
		}
		if j.ParentID != nil {
			m["parentJourneyId"] = *j.ParentID
		}
		if j.EstimatedAt != nil {
			m["estimatedDeliveryAt"] = fmtTime(*j.EstimatedAt)
		}
		return m
	}
	if viewer.activeRole == "requester" {
		m := M{
			"journeyId": j.ID, "routeMode": j.RouteMode, "status": j.Status,
			"sampleIds": sampleIDs, "orderedStops": j.Stops, "legs": legs,
			"totalCostUnits": j.TotalCost,
		}
		if j.ParentID != nil {
			m["parentJourneyId"] = *j.ParentID
		}
		if j.EstimatedAt != nil {
			m["estimatedDeliveryAt"] = fmtTime(*j.EstimatedAt)
		}
		return m
	}
	m := M{
		"journeyId": j.ID, "planVersion": j.PlanVersion, "routeMode": j.RouteMode,
		"status": j.Status, "sampleIds": sampleIDs, "orderedStops": j.Stops, "legs": legs,
		"totalCostUnits": j.TotalCost, "assignedWorkerIds": workerIDs,
		"collectionAssignmentIds": collectionIDs, "nodeAssignmentIds": nodeIDs,
		"laboratoryAssignmentIds": labIDs,
	}
	if j.ParentID != nil {
		m["parentJourneyId"] = *j.ParentID
	}
	if j.EstimatedAt != nil {
		m["estimatedDeliveryAt"] = fmtTime(*j.EstimatedAt)
	}
	if len(collectionIDs) > 0 {
		m["collectionAssignmentId"] = collectionIDs[0]
	}
	if firstT != "" {
		m["firstTransportAssignmentId"] = firstT
	}
	if midT != "" {
		m["middleTransportAssignmentId"] = midT
	}
	if finalT != "" {
		m["finalTransportAssignmentId"] = finalT
	}
	return m
}

func handleReadJourneyPlan(w http.ResponseWriter, r *http.Request) {
	s := requireAuth("read_journey_plan", true, w, r)
	if s == nil {
		return
	}
	var req struct {
		JourneyID string `json:"journeyId"`
	}
	if e := decodeBody(r, &req); e != nil {
		writeAPIErr(w, e)
		return
	}
	j := loadJourney(req.JourneyID)
	if j == nil {
		writeErr(w, 404, "not_found", "journey not found")
		return
	}
	if s.activeRole == "requester" {
		// must own one of the samples
		var own int
		db.QueryRow(`SELECT count(*) FROM journey_samples js JOIN samples sm ON sm.id=js.sample_id JOIN requests rq ON rq.id=sm.request_id WHERE js.journey_id=$1 AND rq.requester_id=$2`, j.ID, s.userID).Scan(&own)
		if own == 0 {
			writeErr(w, 403, "forbidden", "journey does not belong to you")
			return
		}
	}
	writeData(w, 200, journeyPlanJSON(j, s))
}

// ---- operations state ----

func handleReadOperationsState(w http.ResponseWriter, r *http.Request) {
	s := requireAuth("read_operations_state", true, w, r)
	if s == nil {
		return
	}
	samples := []M{}
	rows, _ := db.Query(`SELECT s.id, s.status, s.request_id, r.origin_lat, r.origin_lng, r.delivery_deadline, s.current_holder_id, s.active_journey_id, s.last_lat, s.last_lng, s.location_recorded_at FROM samples s JOIN requests r ON r.id=s.request_id ORDER BY s.created_at DESC LIMIT 500`)
	if rows != nil {
		for rows.Next() {
			var id, status, reqID string
			var olat, olng float64
			var deadline time.Time
			var holder, journey *string
			var lat, lng *float64
			var recAt *time.Time
			rows.Scan(&id, &status, &reqID, &olat, &olng, &deadline, &holder, &journey, &lat, &lng, &recAt)
			m := M{
				"sampleId": id, "status": status, "requestId": reqID,
				"origin": M{"latitude": olat, "longitude": olng},
				"deliveryDeadline": fmtTime(deadline),
				"locationStale":    isStale(recAt),
			}
			if holder != nil {
				m["currentHolderId"] = *holder
			}
			if journey != nil {
				m["activeJourneyId"] = *journey
			}
			if lat != nil {
				m["latestLocation"] = M{"latitude": *lat, "longitude": *lng}
			}
			if recAt != nil {
				m["locationRecordedAt"] = fmtTime(*recAt)
			}
			samples = append(samples, m)
		}
		rows.Close()
	}
	workers := []M{}
	counts := []int{}
	wrows, _ := db.Query(`SELECT DISTINCT u.id, u.full_name, u.available, u.capacity_units, u.last_lat, u.last_lng, u.location_recorded_at FROM users u JOIN user_roles r ON r.user_id=u.id WHERE r.role IN ('collection_professional','delivery_partner','node_handler','laboratory_team')`)
	if wrows != nil {
		for wrows.Next() {
			var id, name string
			var avail bool
			var capU int
			var lat, lng *float64
			var recAt *time.Time
			wrows.Scan(&id, &name, &avail, &capU, &lat, &lng, &recAt)
			var ac int
			db.QueryRow(`SELECT count(*) FROM assignments WHERE worker_id=$1 AND status IN ('accepted','in_progress')`, id).Scan(&ac)
			counts = append(counts, ac)
			m := M{
				"workerId": id, "fullName": name, "roles": userRoles(id),
				"available": avail, "status": ternary(avail, "available", "unavailable"),
				"capacityUnits": capU, "assignmentCount": ac,
				"locationStale": isStale(recAt),
			}
			if lat != nil {
				m["latestLocation"] = M{"latitude": *lat, "longitude": *lng}
			}
			if recAt != nil {
				m["locationRecordedAt"] = fmtTime(*recAt)
			}
			workers = append(workers, m)
		}
		wrows.Close()
	}
	spread := 0
	if len(counts) > 0 {
		mn, mx := counts[0], counts[0]
		for _, c := range counts {
			if c < mn {
				mn = c
			}
			if c > mx {
				mx = c
			}
		}
		spread = mx - mn
	}
	locations := []M{}
	lrows, _ := db.Query(`SELECT id FROM locations ORDER BY created_at`)
	if lrows != nil {
		for lrows.Next() {
			var id string
			lrows.Scan(&id)
			locations = append(locations, locationJSON(id))
		}
		lrows.Close()
	}
	connections := []M{}
	crows, _ := db.Query(`SELECT id FROM connections ORDER BY created_at`)
	if crows != nil {
		for crows.Next() {
			var id string
			crows.Scan(&id)
			connections = append(connections, connectionJSON(id))
		}
		crows.Close()
	}
	handoffs := []M{}
	hrows, _ := db.Query(`SELECT id FROM handoffs ORDER BY created_at DESC LIMIT 200`)
	if hrows != nil {
		for hrows.Next() {
			var id string
			hrows.Scan(&id)
			handoffs = append(handoffs, handoffJSON(id))
		}
		hrows.Close()
	}
	exceptions := []M{}
	erows, _ := db.Query(`SELECT id, exception FROM samples WHERE status='exception' AND exception IS NOT NULL`)
	if erows != nil {
		for erows.Next() {
			var id string
			var ex []byte
			erows.Scan(&id, &ex)
			var exm M
			json.Unmarshal(ex, &exm)
			if exm == nil {
				exm = M{}
			}
			exm["sampleId"] = id
			exceptions = append(exceptions, exm)
		}
		erows.Close()
	}
	writeData(w, 200, M{
		"samples": samples, "workers": workers, "locations": locations,
		"connections": connections, "routes": []M{}, "handoffs": handoffs,
		"delays": []M{}, "exceptions": exceptions,
		"assignmentCountSpread": spread, "ineligibleAssignmentCount": 0,
	})
}

// ---- plan version check helper ----

func checkPlanVersion(j *journeyRow, expected int) *apiErr {
	if expected < 1 {
		return errOf(400, "invalid_plan_version", "expectedPlanVersion must be at least 1")
	}
	if expected != j.PlanVersion {
		return errOf(409, "stale_plan", "the journey plan has changed; reload and retry")
	}
	return nil
}

// ---- cancel ----

func handleCancelJourney(w http.ResponseWriter, r *http.Request) {
	s := requireAuth("cancel_journey", true, w, r)
	if s == nil {
		return
	}
	var req struct {
		JourneyID           string `json:"journeyId"`
		ExpectedPlanVersion int    `json:"expectedPlanVersion"`
	}
	if e := decodeBody(r, &req); e != nil {
		writeAPIErr(w, e)
		return
	}
	j := loadJourney(req.JourneyID)
	if j == nil {
		writeErr(w, 404, "not_found", "journey not found")
		return
	}
	if e := checkPlanVersion(j, req.ExpectedPlanVersion); e != nil {
		writeAPIErr(w, e)
		return
	}
	if j.Status == "completed" || j.Status == "cancelled" {
		writeErr(w, 409, "journey_completed", "journey is already finished")
		return
	}
	db.Exec(`UPDATE journeys SET status='cancelled', plan_version=plan_version+1 WHERE id=$1`, j.ID)
	db.Exec(`UPDATE assignments SET status='cancelled' WHERE journey_id=$1 AND status IN ('pending','offered','accepted','in_progress')`, j.ID)
	for _, sid := range journeySampleIDs(j.ID) {
		db.Exec(`UPDATE samples SET status='cancelled' WHERE id=$1 AND status NOT IN ('received','expired')`, sid)
		audit(s.userID, s.activeRole, "cancel_journey", "sample", sid, true, M{"journeyId": j.ID})
	}
	releaseJourneyCapacity(j.ID)
	audit(s.userID, s.activeRole, "cancel_journey", "journey", j.ID, true, nil)
	emitEvent("journey_cancelled", "journey", j.ID, "", M{"journeyId": j.ID})
	writeData(w, 200, M{"journeyId": j.ID, "status": "cancelled", "planVersion": j.PlanVersion + 1})
}

// ---- reroute ----

// replanJourney cancels unfinished assignments and creates a new plan from the
// current sample position. Completed work is preserved.
func replanJourney(j *journeyRow, actor *sessionInfo, action string) (string, *apiErr) {
	sampleIDs := journeySampleIDs(j.ID)
	if len(sampleIDs) == 0 {
		return "", errOf(409, "invalid_plan", "journey has no samples")
	}
	// cancel unfinished assignments
	db.Exec(`UPDATE assignments SET status='cancelled' WHERE journey_id=$1 AND status IN ('pending','offered')`, j.ID)
	releaseJourneyCapacity(j.ID)
	newJourneyID := ""
	for _, sid := range sampleIDs {
		var status string
		var holder *string
		db.QueryRow(`SELECT status, current_holder_id FROM samples WHERE id=$1`, sid).Scan(&status, &holder)
		if status == "received" || status == "cancelled" || status == "expired" {
			continue
		}
		nid, aerr := createJourneyForSample(sid, holder, "clinic")
		if aerr != nil {
			markSampleException(sid, "replan_failed", aerr.msg)
			if aerr.code == "deadline_unreachable" {
				db.Exec(`UPDATE samples SET status='expired' WHERE id=$1`, sid)
			}
			continue
		}
		newJourneyID = nid
		db.Exec(`UPDATE journeys SET parent_journey_id=$1 WHERE id=$2`, j.ID, nid)
	}
	db.Exec(`UPDATE journeys SET plan_version=plan_version+1, status='replaced' WHERE id=$1`, j.ID)
	audit(actor.userID, actor.activeRole, action, "journey", j.ID, true, M{"replacementJourneyId": newJourneyID})
	return newJourneyID, nil
}

func handleRerouteJourney(w http.ResponseWriter, r *http.Request) {
	s := requireAuth("reroute_journey", true, w, r)
	if s == nil {
		return
	}
	var req struct {
		JourneyID           string `json:"journeyId"`
		ExpectedPlanVersion int    `json:"expectedPlanVersion"`
	}
	if e := decodeBody(r, &req); e != nil {
		writeAPIErr(w, e)
		return
	}
	j := loadJourney(req.JourneyID)
	if j == nil {
		writeErr(w, 404, "not_found", "journey not found")
		return
	}
	if e := checkPlanVersion(j, req.ExpectedPlanVersion); e != nil {
		writeAPIErr(w, e)
		return
	}
	if j.Status == "completed" || j.Status == "cancelled" {
		writeErr(w, 409, "journey_completed", "journey is already finished")
		return
	}
	newID, aerr := replanJourney(j, s, "reroute_journey")
	if aerr != nil {
		writeAPIErr(w, aerr)
		return
	}
	resp := M{"journeyId": j.ID, "status": "replaced", "planVersion": j.PlanVersion + 1}
	if newID != "" {
		nj := loadJourney(newID)
		resp["replacementJourney"] = journeyPlanJSON(nj, s)
	}
	writeData(w, 200, resp)
}

// ---- split ----

func handleSplitJourney(w http.ResponseWriter, r *http.Request) {
	s := requireAuth("split_journey", true, w, r)
	if s == nil {
		return
	}
	var req struct {
		JourneyID           string   `json:"journeyId"`
		SampleIDs           []string `json:"sampleIds"`
		ExpectedPlanVersion int      `json:"expectedPlanVersion"`
	}
	if e := decodeBody(r, &req); e != nil {
		writeAPIErr(w, e)
		return
	}
	j := loadJourney(req.JourneyID)
	if j == nil {
		writeErr(w, 404, "not_found", "journey not found")
		return
	}
	if e := checkPlanVersion(j, req.ExpectedPlanVersion); e != nil {
		writeAPIErr(w, e)
		return
	}
	existing := journeySampleIDs(j.ID)
	exSet := map[string]bool{}
	for _, id := range existing {
		exSet[id] = true
	}
	for _, sid := range req.SampleIDs {
		if !exSet[sid] {
			writeErr(w, 409, "invalid_plan", "sample is not part of this journey")
			return
		}
	}
	// move given samples into a new journey cloned from remaining plan
	newJourneyID := newUUID()
	stopsJSON, _ := json.Marshal(j.Stops)
	db.Exec(`INSERT INTO journeys(id,parent_journey_id,plan_version,route_mode,status,estimated_delivery_at,total_cost_units,target_laboratory_id,stops)
		VALUES($1,$2,1,$3,'planned',$4,$5,$6,$7)`, newJourneyID, j.ID, j.RouteMode, j.EstimatedAt, j.TotalCost, j.TargetLabID, stopsJSON)
	for _, sid := range req.SampleIDs {
		db.Exec(`UPDATE journey_samples SET journey_id=$1 WHERE journey_id=$2 AND sample_id=$3`, newJourneyID, j.ID, sid)
		db.Exec(`UPDATE samples SET active_journey_id=$1 WHERE id=$2`, newJourneyID, sid)
		db.Exec(`UPDATE assignments SET journey_id=$1 WHERE journey_id=$2 AND sample_id=$3 AND status IN ('pending','offered')`, newJourneyID, j.ID, sid)
	}
	db.Exec(`UPDATE journeys SET plan_version=plan_version+1 WHERE id=$1`, j.ID)
	audit(s.userID, s.activeRole, "split_journey", "journey", j.ID, true, M{"splitJourneyId": newJourneyID, "sampleIds": req.SampleIDs})
	nj := loadJourney(newJourneyID)
	writeData(w, 200, M{
		"journeyId": j.ID, "planVersion": j.PlanVersion + 1, "status": j.Status,
		"splitJourney": journeyPlanJSON(nj, s),
	})
}

// ---- merge ----

func handleMergeJourneys(w http.ResponseWriter, r *http.Request) {
	s := requireAuth("merge_journeys", true, w, r)
	if s == nil {
		return
	}
	var req struct {
		TargetJourneyID       string   `json:"targetJourneyId"`
		SourceJourneyIDs      []string `json:"sourceJourneyIds"`
		ExpectedPlanVersion   int      `json:"expectedPlanVersion"`
	}
	if e := decodeBody(r, &req); e != nil {
		writeAPIErr(w, e)
		return
	}
	tj := loadJourney(req.TargetJourneyID)
	if tj == nil {
		writeErr(w, 404, "not_found", "target journey not found")
		return
	}
	if e := checkPlanVersion(tj, req.ExpectedPlanVersion); e != nil {
		writeAPIErr(w, e)
		return
	}
	// validate compatibility of all samples
	allSamples := journeySampleIDs(tj.ID)
	for _, srcID := range req.SourceJourneyIDs {
		sj := loadJourney(srcID)
		if sj == nil {
			writeErr(w, 404, "not_found", "source journey not found")
			return
		}
		if sj.Status == "completed" || sj.Status == "cancelled" {
			writeErr(w, 409, "journey_completed", "source journey is already finished")
			return
		}
		allSamples = append(allSamples, journeySampleIDs(srcID)...)
	}
	if aerr := validateBatchCompatibility(allSamples); aerr != nil {
		writeAPIErr(w,&apiErr{409, "incompatible_samples", aerr.msg})
		return
	}
	for _, srcID := range req.SourceJourneyIDs {
		for _, sid := range journeySampleIDs(srcID) {
			db.Exec(`UPDATE journey_samples SET journey_id=$1 WHERE journey_id=$2 AND sample_id=$3`, tj.ID, srcID, sid)
			db.Exec(`UPDATE samples SET active_journey_id=$1 WHERE id=$2`, tj.ID, sid)
			db.Exec(`UPDATE assignments SET journey_id=$1 WHERE journey_id=$2 AND sample_id=$3 AND status IN ('pending','offered')`, tj.ID, srcID, sid)
		}
		db.Exec(`UPDATE journeys SET status='merged' WHERE id=$1`, srcID)
	}
	db.Exec(`UPDATE journeys SET plan_version=plan_version+1, route_mode='batched' WHERE id=$1`, tj.ID)
	audit(s.userID, s.activeRole, "merge_journeys", "journey", tj.ID, true, M{"sourceJourneyIds": req.SourceJourneyIDs})
	writeData(w, 200, M{"journeyId": tj.ID, "planVersion": tj.PlanVersion + 1, "status": tj.Status, "sampleIds": journeySampleIDs(tj.ID)})
}

func validateBatchCompatibility(sampleIDs []string) *apiErr {
	types := map[string]*sampleTypeInfo{}
	for _, sid := range sampleIDs {
		st := loadSampleType(requestSampleType(sid))
		if st == nil {
			continue
		}
		if !st.BatchingAllowed && len(sampleIDs) > 1 {
			return errOf(409, "incompatible_samples", "sample type "+st.Name+" must not be batched")
		}
		for otherID, other := range types {
			for _, inc := range st.Incompatible {
				if inc == otherID {
					return errOf(409, "incompatible_samples", "sample types "+st.Name+" and "+other.Name+" are incompatible")
				}
			}
			for _, inc := range other.Incompatible {
				if inc == st.ID {
					return errOf(409, "incompatible_samples", "sample types "+st.Name+" and "+other.Name+" are incompatible")
				}
			}
			if st.ContainerType != "" && other.ContainerType != "" && st.ContainerType != other.ContainerType {
				return errOf(409, "incompatible_samples", "container types are incompatible")
			}
			if st.TempMin > other.TempMax || other.TempMin > st.TempMax {
				return errOf(409, "incompatible_samples", "temperature ranges are incompatible")
			}
		}
		types[st.ID] = st
	}
	return nil
}

// ---- edit active plan ----

func handleEditActivePlan(w http.ResponseWriter, r *http.Request) {
	s := requireAuth("edit_active_plan", true, w, r)
	if s == nil {
		return
	}
	var req struct {
		JourneyID           string          `json:"journeyId"`
		ExpectedPlanVersion int             `json:"expectedPlanVersion"`
		ChangeType          string          `json:"changeType"`
		Payload             json.RawMessage `json:"payload"`
	}
	if e := decodeBody(r, &req); e != nil {
		writeAPIErr(w, e)
		return
	}
	j := loadJourney(req.JourneyID)
	if j == nil {
		writeErr(w, 404, "not_found", "journey not found")
		return
	}
	if e := checkPlanVersion(j, req.ExpectedPlanVersion); e != nil {
		writeAPIErr(w, e)
		return
	}
	if j.Status == "completed" || j.Status == "cancelled" {
		writeErr(w, 409, "journey_completed", "journey is already finished")
		return
	}
	switch req.ChangeType {
	case "cancel_work":
		db.Exec(`UPDATE journeys SET status='cancelled', plan_version=plan_version+1 WHERE id=$1`, j.ID)
		db.Exec(`UPDATE assignments SET status='cancelled' WHERE journey_id=$1 AND status IN ('pending','offered','accepted','in_progress')`, j.ID)
		for _, sid := range journeySampleIDs(j.ID) {
			db.Exec(`UPDATE samples SET status='cancelled' WHERE id=$1 AND status NOT IN ('received','expired')`, sid)
		}
		releaseJourneyCapacity(j.ID)
		audit(s.userID, s.activeRole, "edit_active_plan", "journey", j.ID, true, M{"changeType": req.ChangeType})
		writeData(w, 200, M{"journeyId": j.ID, "status": "cancelled", "planVersion": j.PlanVersion + 1})
		return
	case "replace_worker", "reassign_worker":
		var p struct {
			AssignmentID string `json:"assignmentId"`
			WorkerID     string `json:"workerId"`
		}
		json.Unmarshal(req.Payload, &p)
		a := loadAssignment(p.AssignmentID)
		if a == nil || a.JourneyID != j.ID {
			writeErr(w, 404, "not_found", "assignment not found in journey")
			return
		}
		if a.Status == "completed" {
			writeErr(w, 409, "invalid_plan", "cannot reassign completed work")
			return
		}
		db.Exec(`UPDATE assignments SET status='pending', offered_to=NULL, worker_id=NULL, offer_expires_at=NULL WHERE id=$1`, a.ID)
		db.Exec(`UPDATE journeys SET plan_version=plan_version+1 WHERE id=$1`, j.ID)
		a2 := loadAssignment(a.ID)
		offerAssignment(a2)
		audit(s.userID, s.activeRole, "edit_active_plan", "journey", j.ID, true, M{"changeType": req.ChangeType, "assignmentId": a.ID})
		writeData(w, 200, M{"journeyId": j.ID, "status": j.Status, "planVersion": j.PlanVersion + 1})
		return
	case "reroute":
		newID, aerr := replanJourney(j, s, "edit_active_plan")
		if aerr != nil {
			writeAPIErr(w, aerr)
			return
		}
		resp := M{"journeyId": j.ID, "status": "replaced", "planVersion": j.PlanVersion + 1}
		if newID != "" {
			resp["replacementJourney"] = journeyPlanJSON(loadJourney(newID), s)
		}
		writeData(w, 200, resp)
		return
	default:
		writeErr(w, 400, "invalid_plan", "unsupported changeType: "+req.ChangeType)
		return
	}
}

// ---- disruption ----

func handleReportDisruption(w http.ResponseWriter, r *http.Request) {
	s := requireAuth("report_disruption", true, w, r)
	if s == nil {
		return
	}
	var req struct {
		ResourceType string `json:"resourceType"`
		ResourceID   string `json:"resourceId"`
		Reason       string `json:"reason"`
		OccurredAt   string `json:"occurredAt"`
	}
	if e := decodeBody(r, &req); e != nil {
		writeAPIErr(w, e)
		return
	}
	switch req.ResourceType {
	case "worker", "node", "route", "laboratory", "capacity_pool":
	default:
		writeErr(w, 400, "invalid_json", "resourceType must be worker, node, route, laboratory or capacity_pool")
		return
	}
	occurredAt := time.Now()
	if req.OccurredAt != "" {
		if t, ok := parseTime(req.OccurredAt); ok {
			occurredAt = t
		}
	}
	// mark resource unavailable
	switch req.ResourceType {
	case "worker":
		res, _ := db.Exec(`UPDATE users SET available=FALSE WHERE id=$1`, req.ResourceID)
		if n, _ := res.RowsAffected(); n == 0 {
			writeErr(w, 404, "not_found", "resource not found")
			return
		}
	case "node", "laboratory", "capacity_pool":
		res, _ := db.Exec(`UPDATE locations SET active=FALSE WHERE id=$1`, req.ResourceID)
		if n, _ := res.RowsAffected(); n == 0 {
			res2, _ := db.Exec(`UPDATE connections SET active=FALSE WHERE id=$1`, req.ResourceID)
			if n2, _ := res2.RowsAffected(); n2 == 0 {
				writeErr(w, 404, "not_found", "resource not found")
				return
			}
		}
	case "route":
		res, _ := db.Exec(`UPDATE connections SET active=FALSE WHERE id=$1`, req.ResourceID)
		if n, _ := res.RowsAffected(); n == 0 {
			writeErr(w, 404, "not_found", "resource not found")
			return
		}
	}
	bumpNetworkRevision()
	recomputeServiceabilitySnapshot()
	// find affected journeys: active journeys with unfinished assignments touching the resource
	affectedSamples := []string{}
	replacements := []string{}
	replanStatus := "not_required"
	jrows, _ := db.Query(`SELECT DISTINCT j.id FROM journeys j JOIN assignments a ON a.journey_id=j.id
		WHERE j.status IN ('planned','in_progress') AND a.status IN ('pending','offered','accepted','in_progress')
		AND (a.worker_id=$1 OR a.node_id=$1 OR a.laboratory_id=$1 OR a.from_location_id=$1 OR a.to_location_id=$1)`, req.ResourceID)
	var journeyIDs []string
	if jrows != nil {
		for jrows.Next() {
			var id string
			jrows.Scan(&id)
			journeyIDs = append(journeyIDs, id)
		}
		jrows.Close()
	}
	for _, jid := range journeyIDs {
		j := loadJourney(jid)
		affectedSamples = append(affectedSamples, journeySampleIDs(jid)...)
		newID, aerr := replanJourney(j, s, "replan_after_disruption")
		if aerr != nil {
			replanStatus = "exception"
			continue
		}
		if newID != "" {
			replacements = append(replacements, newID)
			replanStatus = "replaced"
		} else {
			replanStatus = "expired"
		}
	}
	id := newUUID()
	db.Exec(`INSERT INTO disruptions(id,resource_type,resource_id,reason,occurred_at,replan_status,affected_sample_ids,replacement_plan_ids) VALUES($1,$2,$3,$4,$5,$6,$7,$8)`,
		id, req.ResourceType, req.ResourceID, req.Reason, occurredAt, replanStatus, pq.Array(affectedSamples), pq.Array(replacements))
	audit(s.userID, s.activeRole, "report_disruption", req.ResourceType, req.ResourceID, true, M{"reason": req.Reason, "replanStatus": replanStatus})
	emitEvent("disruption", req.ResourceType, req.ResourceID, "dispatcher", M{"resourceType": req.ResourceType, "resourceId": req.ResourceID})
	writeData(w, 201, M{
		"disruptionId": id, "replanStatus": replanStatus,
		"affectedSampleIds": affectedSamples, "replacementPlanIds": replacements,
	})
}

// ---- audit search ----

func handleSearchAudit(w http.ResponseWriter, r *http.Request) {
	s := requireAuth("search_audit_trail", true, w, r)
	if s == nil {
		return
	}
	var req struct {
		Query      string `json:"query"`
		EntityType string `json:"entityType"`
		EntityID   string `json:"entityId"`
		ActorID    string `json:"actorId"`
		Action     string `json:"action"`
		Limit      int    `json:"limit"`
		Offset     int    `json:"offset"`
		Order      string `json:"order"`
	}
	if e := decodeBody(r, &req); e != nil {
		writeAPIErr(w, e)
		return
	}
	limit := req.Limit
	if limit <= 0 || limit > 500 {
		limit = 100
	}
	offset := req.Offset
	if offset < 0 {
		offset = 0
	}
	order := "newest_first"
	if req.Order == "oldest_first" {
		order = "oldest_first"
	}
	where := "1=1"
	args := []any{}
	add := func(cond string, v any) {
		args = append(args, v)
		where += " AND " + cond + "$" + strconv.Itoa(len(args))
	}
	if req.EntityType != "" {
		add("entity_type=", req.EntityType)
	}
	if req.EntityID != "" {
		add("entity_id=", req.EntityID)
	}
	if req.ActorID != "" {
		add("actor_id=", req.ActorID)
	}
	if req.Action != "" {
		add("action=", req.Action)
	}
	if req.Query != "" {
		args = append(args, "%"+req.Query+"%")
		where += " AND (action ILIKE $" + strconv.Itoa(len(args)) + " OR entity_id ILIKE $" + strconv.Itoa(len(args)) + " OR details::text ILIKE $" + strconv.Itoa(len(args)) + ")"
	}
	var total int
	db.QueryRow(`SELECT count(*) FROM audit_log WHERE `+where, args...).Scan(&total)
	dir := "DESC"
	if order == "oldest_first" {
		dir = "ASC"
	}
	args = append(args, limit, offset)
	rows, err := db.Query(`SELECT audit_id,actor_id,role,action,entity_type,entity_id,success,occurred_at,details FROM audit_log WHERE `+where+` ORDER BY seq `+dir+` LIMIT $`+strconv.Itoa(len(args)-1)+` OFFSET $`+strconv.Itoa(len(args)), args...)
	if err != nil {
		writeErr(w, 500, "internal_error", err.Error())
		return
	}
	defer rows.Close()
	entries := []M{}
	for rows.Next() {
		var aid, actorID, role, action, et, eid string
		var success bool
		var at time.Time
		var details []byte
		rows.Scan(&aid, &actorID, &role, &action, &et, &eid, &success, &at, &details)
		var det M
		json.Unmarshal(details, &det)
		if det == nil {
			det = M{}
		}
		entries = append(entries, M{
			"auditId": aid, "actorId": actorID, "role": role, "actorRole": role,
			"action": action, "entityType": et, "entityId": eid,
			"success": success, "occurredAt": fmtTime(at), "details": det,
		})
	}
	hasMore := offset+len(entries) < total
	resp := M{
		"entries": entries, "total": total, "returned": len(entries),
		"offset": offset, "limit": limit, "order": order, "hasMore": hasMore,
	}
	if hasMore {
		resp["nextOffset"] = offset + len(entries)
	}
	writeData(w, 200, resp)
}

// ---- sample reads ----

func canViewSample(s *sessionInfo, sampleID string) bool {
	if s.activeRole == "dispatcher" || s.activeRole == "administrator" {
		return true
	}
	if s.activeRole == "requester" {
		var own int
		db.QueryRow(`SELECT count(*) FROM samples sm JOIN requests r ON r.id=sm.request_id WHERE sm.id=$1 AND r.requester_id=$2`, sampleID, s.userID).Scan(&own)
		return own > 0
	}
	// workers: involved via assignment or custody
	var n int
	db.QueryRow(`SELECT (SELECT count(*) FROM assignments WHERE sample_id=$1 AND (worker_id=$2 OR offered_to=$2)) + (SELECT count(*) FROM samples WHERE id=$1 AND current_holder_id=$2)`, sampleID, s.userID).Scan(&n)
	return n > 0
}

func handleReadSampleState(w http.ResponseWriter, r *http.Request) {
	s := requireAuth("read_sample_state", false, w, r)
	if s == nil {
		return
	}
	id := r.PathValue("sampleId")
	if !canViewSample(s, id) {
		writeErr(w, 403, "forbidden", "you may not view this sample")
		return
	}
	m := readSampleState(id)
	if m == nil {
		writeErr(w, 404, "not_found", "sample not found")
		return
	}
	writeData(w, 200, m)
}

func handleReadSampleLifecycle(w http.ResponseWriter, r *http.Request) {
	s := requireAuth("read_sample_lifecycle", false, w, r)
	if s == nil {
		return
	}
	id := r.PathValue("sampleId")
	if !canViewSample(s, id) {
		writeErr(w, 403, "forbidden", "you may not view this sample")
		return
	}
	m := readSampleLifecycle(id)
	if m == nil {
		writeErr(w, 404, "not_found", "sample not found")
		return
	}
	writeData(w, 200, m)
}

// ---- serviceability snapshot ----

func handleReadServiceabilitySnapshot(w http.ResponseWriter, r *http.Request) {
	s := requireAuth("read_serviceability_snapshot", true, w, r)
	if s == nil {
		return
	}
	var version int
	var computedAt time.Time
	var rev int
	var payload []byte
	err := db.QueryRow(`SELECT version, computed_at, network_revision, payload FROM serviceability_snapshots WHERE status='complete' ORDER BY version DESC LIMIT 1`).Scan(&version, &computedAt, &rev, &payload)
	if err != nil {
		writeData(w, 200, M{"version": 0, "computedAt": fmtTime(time.Now()), "networkRevision": 0, "regions": []M{}, "activeCollectionPointCount": 0})
		return
	}
	var p M
	json.Unmarshal(payload, &p)
	writeData(w, 200, M{
		"version": version, "computedAt": fmtTime(computedAt), "networkRevision": rev,
		"regions": p["regions"], "activeCollectionPointCount": p["activeCollectionPointCount"],
	})
}

