// ---- split ----

func handleSplitJourney(w http.ResponseWriter, r *http.Request) {
	s := requireAuth("split_journey", true, w, r)
	if s == nil {
		return
	}
	var req struct {
		JourneyID           string   `json:"journeyId"`
		SampleIDs           []string `json:"sampleIds"`
		ExpectedPlanVersion int      `json:"expectedPlanVersion"`
		IdempotencyKey      string   `json:"idempotencyKey"`
	}
	if e := decodeBody(r, &req); e != nil {
		writeAPIErr(w, e)
		return
	}
	j := loadJourney(req.JourneyID)
	if j == nil {
		writeErr(w, 404, "not_found", "journey not found")
		return
	}
	if e := checkPlanVersion(j, req.ExpectedPlanVersion); e != nil {
		writeAPIErr(w, e)
		return
	}
	existing := journeySampleIDs(j.ID)
	exSet := map[string]bool{}
	for _, id := range existing {
		exSet[id] = true
	}
	for _, sid := range req.SampleIDs {
		if !exSet[sid] {
			writeErr(w, 409, "invalid_plan", "sample is not part of this journey")
			return
		}
	}
	// move given samples into a new journey cloned from remaining plan
	newJourneyID := newUUID()
	stopsJSON, _ := json.Marshal(j.Stops)
	db.Exec(`INSERT INTO journeys(id,parent_journey_id,plan_version,route_mode,status,estimated_delivery_at,total_cost_units,target_laboratory_id,stops)
		VALUES($1,$2,1,$3,'planned',$4,$5,$6,$7)`, newJourneyID, j.ID, j.RouteMode, j.EstimatedAt, j.TotalCost, j.TargetLabID, stopsJSON)
	for _, sid := range req.SampleIDs {
		db.Exec(`UPDATE journey_samples SET journey_id=$1 WHERE journey_id=$2 AND sample_id=$3`, newJourneyID, j.ID, sid)
		db.Exec(`UPDATE samples SET active_journey_id=$1 WHERE id=$2`, newJourneyID, sid)
		db.Exec(`UPDATE assignments SET journey_id=$1 WHERE journey_id=$2 AND sample_id=$3 AND status IN ('pending','offered')`, newJourneyID, j.ID, sid)
	}
	db.Exec(`UPDATE journeys SET plan_version=plan_version+1 WHERE id=$1`, j.ID)
	audit(s.userID, s.activeRole, "split_journey", "journey", j.ID, true, M{"splitJourneyId": newJourneyID, "sampleIds": req.SampleIDs})
	nj := loadJourney(newJourneyID)
	writeData(w, 200, M{
		"journeyId": j.ID, "planVersion": j.PlanVersion + 1, "status": j.Status,
		"splitJourney": journeyPlanJSON(nj, s),
	})
}

// ---- merge ----

func handleMergeJourneys(w http.ResponseWriter, r *http.Request) {
	s := requireAuth("merge_journeys", true, w, r)
	if s == nil {
		return
	}
	var req struct {
		TargetJourneyID     string   `json:"targetJourneyId"`
		SourceJourneyIDs    []string `json:"sourceJourneyIds"`
		ExpectedPlanVersion int      `json:"expectedPlanVersion"`
		IdempotencyKey      string   `json:"idempotencyKey"`
	}
	if e := decodeBody(r, &req); e != nil {
		writeAPIErr(w, e)
		return
	}
	tj := loadJourney(req.TargetJourneyID)
	if tj == nil {
		writeErr(w, 404, "not_found", "target journey not found")
		return
	}
	if e := checkPlanVersion(tj, req.ExpectedPlanVersion); e != nil {
		writeAPIErr(w, e)
		return
	}
	// validate compatibility of all samples
	allSamples := journeySampleIDs(tj.ID)
	for _, srcID := range req.SourceJourneyIDs {
		sj := loadJourney(srcID)
		if sj == nil {
			writeErr(w, 404, "not_found", "source journey not found")
			return
		}
		if sj.Status == "completed" || sj.Status == "cancelled" {
			writeErr(w, 409, "journey_completed", "source journey is already finished")
			return
		}
		allSamples = append(allSamples, journeySampleIDs(srcID)...)
	}
	if aerr := validateBatchCompatibility(allSamples); aerr != nil {
		writeAPIErr(w,&apiErr{409, "incompatible_samples", aerr.msg})
		return
	}
	for _, srcID := range req.SourceJourneyIDs {
		for _, sid := range journeySampleIDs(srcID) {
			db.Exec(`UPDATE journey_samples SET journey_id=$1 WHERE journey_id=$2 AND sample_id=$3`, tj.ID, srcID, sid)
			db.Exec(`UPDATE samples SET active_journey_id=$1 WHERE id=$2`, tj.ID, sid)
			db.Exec(`UPDATE assignments SET journey_id=$1 WHERE journey_id=$2 AND sample_id=$3 AND status IN ('pending','offered')`, tj.ID, srcID, sid)
		}
		db.Exec(`UPDATE journeys SET status='merged' WHERE id=$1`, srcID)
	}
	db.Exec(`UPDATE journeys SET plan_version=plan_version+1, route_mode='batched' WHERE id=$1`, tj.ID)
	audit(s.userID, s.activeRole, "merge_journeys", "journey", tj.ID, true, M{"sourceJourneyIds": req.SourceJourneyIDs})
	writeData(w, 200, M{"journeyId": tj.ID, "planVersion": tj.PlanVersion + 1, "status": tj.Status, "sampleIds": journeySampleIDs(tj.ID)})
}

func validateBatchCompatibility(sampleIDs []string) *apiErr {
	types := map[string]*sampleTypeInfo{}
	for _, sid := range sampleIDs {
		st := loadSampleType(requestSampleType(sid))
		if st == nil {
			continue
		}
		if !st.BatchingAllowed && len(sampleIDs) > 1 {
			return errOf(409, "incompatible_samples", "sample type "+st.Name+" must not be batched")
		}
		for otherID, other := range types {
			for _, inc := range st.Incompatible {
				if inc == otherID {
					return errOf(409, "incompatible_samples", "sample types "+st.Name+" and "+other.Name+" are incompatible")
				}
			}
			for _, inc := range other.Incompatible {
				if inc == st.ID {
					return errOf(409, "incompatible_samples", "sample types "+st.Name+" and "+other.Name+" are incompatible")
				}
			}
			if st.ContainerType != "" && other.ContainerType != "" && st.ContainerType != other.ContainerType {
				return errOf(409, "incompatible_samples", "container types are incompatible")
			}
			if st.TempMin > other.TempMax || other.TempMin > st.TempMax {
				return errOf(409, "incompatible_samples", "temperature ranges are incompatible")
			}
		}
		types[st.ID] = st
	}
	return nil
}

// ---- edit active plan ----

func handleEditActivePlan(w http.ResponseWriter, r *http.Request) {
	s := requireAuth("edit_active_plan", true, w, r)
	if s == nil {
		return
	}
	var req struct {
		JourneyID           string          `json:"journeyId"`
		ExpectedPlanVersion int             `json:"expectedPlanVersion"`
		ChangeType          string          `json:"changeType"`
		Payload             json.RawMessage `json:"changes"`
		IdempotencyKey      string          `json:"idempotencyKey"`
	}
	if e := decodeBody(r, &req); e != nil {
		writeAPIErr(w, e)
		return
	}
	j := loadJourney(req.JourneyID)
	if j == nil {
		writeErr(w, 404, "not_found", "journey not found")
		return
	}
	if e := checkPlanVersion(j, req.ExpectedPlanVersion); e != nil {
		writeAPIErr(w, e)
		return
	}
	if j.Status == "completed" || j.Status == "cancelled" {
		writeErr(w, 409, "journey_completed", "journey is already finished")
		return
	}
	switch req.ChangeType {
	case "cancel_work":
		db.Exec(`UPDATE journeys SET status='cancelled', plan_version=plan_version+1 WHERE id=$1`, j.ID)
		db.Exec(`UPDATE assignments SET status='cancelled' WHERE journey_id=$1 AND status IN ('pending','offered','accepted','in_progress')`, j.ID)
		for _, sid := range journeySampleIDs(j.ID) {
			db.Exec(`UPDATE samples SET status='cancelled' WHERE id=$1 AND status NOT IN ('received','expired')`, sid)
		}
		releaseJourneyCapacity(j.ID)
		audit(s.userID, s.activeRole, "edit_active_plan", "journey", j.ID, true, M{"changeType": req.ChangeType})
		writeData(w, 200, M{"journeyId": j.ID, "status": "cancelled", "planVersion": j.PlanVersion + 1})
		return
	case "replace_worker", "reassign_worker":
		var p struct {
			AssignmentID string `json:"assignmentId"`
			WorkerID     string `json:"workerId"`
		}
		json.Unmarshal(req.Payload, &p)
		a := loadAssignment(p.AssignmentID)
		if a == nil || a.JourneyID != j.ID {
			writeErr(w, 404, "not_found", "assignment not found in journey")
			return
		}
		if a.Status == "completed" {
			writeErr(w, 409, "invalid_plan", "cannot reassign completed work")
			return
		}
		db.Exec(`UPDATE assignments SET status='pending', offered_to=NULL, worker_id=NULL, offer_expires_at=NULL WHERE id=$1`, a.ID)
		db.Exec(`UPDATE journeys SET plan_version=plan_version+1 WHERE id=$1`, j.ID)
		a2 := loadAssignment(a.ID)
		offerAssignment(a2)
		audit(s.userID, s.activeRole, "edit_active_plan", "journey", j.ID, true, M{"changeType": req.ChangeType, "assignmentId": a.ID})
		writeData(w, 200, M{"journeyId": j.ID, "status": j.Status, "planVersion": j.PlanVersion + 1})
		return
	case "reroute":
		newID, aerr := replanJourney(j, s, "edit_active_plan")
		if aerr != nil {
			writeAPIErr(w, aerr)
			return
		}
		resp := M{"journeyId": j.ID, "status": "replaced", "planVersion": j.PlanVersion + 1}
		if newID != "" {
			resp["replacementJourney"] = journeyPlanJSON(loadJourney(newID), s)
		}
		writeData(w, 200, resp)
		return
	default:
		writeErr(w, 400, "invalid_plan", "unsupported changeType: "+req.ChangeType)
		return
	}
}

// ---- disruption ----

func handleReportDisruption(w http.ResponseWriter, r *http.Request) {
	s := requireAuth("report_disruption", true, w, r)
	if s == nil {
		return
	}
	var req struct {
		ResourceType   string `json:"resourceType"`
		ResourceID     string `json:"resourceId"`
		Reason         string `json:"reason"`
		OccurredAt     string `json:"occurredAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if e := decodeBody(r, &req); e != nil {
		writeAPIErr(w, e)
		return
	}
	switch req.ResourceType {
	case "worker", "node", "route", "laboratory", "capacity_pool", "location", "connection", "capacity":
	default:
		writeErr(w, 400, "invalid_json", "resourceType must be worker, node, route, laboratory, location, connection or capacity")
		return
	}
	occurredAt := time.Now()
	if req.OccurredAt != "" {
		if t, ok := parseTime(req.OccurredAt); ok {
			occurredAt = t
		}
	}
	// mark resource unavailable
	switch req.ResourceType {
	case "worker":
		res, _ := db.Exec(`UPDATE users SET available=FALSE WHERE id=$1`, req.ResourceID)
		if n, _ := res.RowsAffected(); n == 0 {
			writeErr(w, 404, "not_found", "resource not found")
			return
		}
	case "node", "laboratory", "capacity_pool":
		res, _ := db.Exec(`UPDATE locations SET active=FALSE WHERE id=$1`, req.ResourceID)
		if n, _ := res.RowsAffected(); n == 0 {
			res2, _ := db.Exec(`UPDATE connections SET active=FALSE WHERE id=$1`, req.ResourceID)
			if n2, _ := res2.RowsAffected(); n2 == 0 {
				writeErr(w, 404, "not_found", "resource not found")
				return
			}
		}
	case "route":
		res, _ := db.Exec(`UPDATE connections SET active=FALSE WHERE id=$1`, req.ResourceID)
		if n, _ := res.RowsAffected(); n == 0 {
			writeErr(w, 404, "not_found", "resource not found")
			return
		}
	}
	bumpNetworkRevision()
	recomputeServiceabilitySnapshot()
	// find affected journeys: active journeys with unfinished assignments touching the resource
	affectedSamples := []string{}
	replacements := []string{}
	replanStatus := "not_required"
	jrows, _ := db.Query(`SELECT DISTINCT j.id FROM journeys j JOIN assignments a ON a.journey_id=j.id
		WHERE j.status IN ('planned','in_progress') AND a.status IN ('pending','offered','accepted','in_progress')
		AND (a.worker_id=$1 OR a.node_id=$1 OR a.laboratory_id=$1 OR a.from_location_id=$1 OR a.to_location_id=$1)`, req.ResourceID)
	var journeyIDs []string
	if jrows != nil {
		for jrows.Next() {
			var id string
			jrows.Scan(&id)
			journeyIDs = append(journeyIDs, id)
		}
		jrows.Close()
	}
	for _, jid := range journeyIDs {
		j := loadJourney(jid)
		affectedSamples = append(affectedSamples, journeySampleIDs(jid)...)
		newID, aerr := replanJourney(j, s, "replan_after_disruption")
		if aerr != nil {
			replanStatus = "exception"
			continue
		}
		if newID != "" {
			replacements = append(replacements, newID)
			replanStatus = "replaced"
		} else {
			replanStatus = "expired"
		}
	}
	id := newUUID()
	db.Exec(`INSERT INTO disruptions(id,resource_type,resource_id,reason,occurred_at,replan_status,affected_sample_ids,replacement_plan_ids) VALUES($1,$2,$3,$4,$5,$6,$7,$8)`,
		id, req.ResourceType, req.ResourceID, req.Reason, occurredAt, replanStatus, pq.Array(affectedSamples), pq.Array(replacements))
	audit(s.userID, s.activeRole, "report_disruption", req.ResourceType, req.ResourceID, true, M{"reason": req.Reason, "replanStatus": replanStatus})
	emitEvent("disruption", req.ResourceType, req.ResourceID, "dispatcher", M{"resourceType": req.ResourceType, "resourceId": req.ResourceID})
	writeData(w, 201, M{
		"disruptionId": id, "replanStatus": replanStatus,
		"affectedSampleIds": affectedSamples, "replacementPlanIds": replacements,
	})
}

// ---- audit search ----

func handleSearchAudit(w http.ResponseWriter, r *http.Request) {
	s := requireAuth("search_audit_trail", true, w, r)
	if s == nil {
		return
	}
	var req struct {
		Query      string `json:"query"`
		EntityType string `json:"entityType"`
		EntityID   string `json:"entityId"`
		ActorID    string `json:"actorId"`
		Action     string `json:"action"`
		Role       string `json:"role"`
		Success    *bool  `json:"success"`
		FromTime   string `json:"fromTime"`
		ToTime     string `json:"toTime"`
		Limit      int    `json:"limit"`
		Offset     int    `json:"offset"`
		Order      string `json:"order"`
	}
	if e := decodeBody(r, &req); e != nil {
		writeAPIErr(w, e)
		return
	}
	limit := req.Limit
	if limit <= 0 || limit > 500 {
		limit = 100
	}
	offset := req.Offset
	if offset < 0 {
		offset = 0
	}
	order := "newest_first"
	if req.Order == "oldest_first" {
		order = "oldest_first"
	}
	where := "1=1"
	args := []any{}
	add := func(cond string, v any) {
		args = append(args, v)
		where += " AND " + cond + "$" + strconv.Itoa(len(args))
	}
	if req.EntityType != "" {
		add("entity_type=", req.EntityType)
	}
	if req.EntityID != "" {
		add("entity_id=", req.EntityID)
	}
	if req.ActorID != "" {
		add("actor_id=", req.ActorID)
	}
	if req.Action != "" {
		add("action=", req.Action)
	}
	if req.Query != "" {
		args = append(args, "%"+req.Query+"%")
		where += " AND (action ILIKE $" + strconv.Itoa(len(args)) + " OR entity_id ILIKE $" + strconv.Itoa(len(args)) + " OR details::text ILIKE $" + strconv.Itoa(len(args)) + ")"
	}
	var total int
	db.QueryRow(`SELECT count(*) FROM audit_log WHERE `+where, args...).Scan(&total)
	dir := "DESC"
	if order == "oldest_first" {
		dir = "ASC"
	}
	args = append(args, limit, offset)
	rows, err := db.Query(`SELECT audit_id,actor_id,role,action,entity_type,entity_id,success,occurred_at,details FROM audit_log WHERE `+where+` ORDER BY seq `+dir+` LIMIT $`+strconv.Itoa(len(args)-1)+` OFFSET $`+strconv.Itoa(len(args)), args...)
	if err != nil {
		writeErr(w, 500, "internal_error", err.Error())
		return
	}
	defer rows.Close()
	entries := []M{}
	for rows.Next() {
		var aid, actorID, role, action, et, eid string
		var success bool
		var at time.Time
		var details []byte
		rows.Scan(&aid, &actorID, &role, &action, &et, &eid, &success, &at, &details)
		var det M
		json.Unmarshal(details, &det)
		if det == nil {
			det = M{}
		}
		entries = append(entries, M{
			"auditId": aid, "actorId": actorID, "role": role, "actorRole": role,
			"action": action, "entityType": et, "entityId": eid,
			"success": success, "occurredAt": fmtTime(at), "details": det,
		})
	}
	hasMore := offset+len(entries) < total
	resp := M{
		"entries": entries, "total": total, "returned": len(entries),
		"offset": offset, "limit": limit, "order": order, "hasMore": hasMore,
	}
	if hasMore {
		resp["nextOffset"] = offset + len(entries)
	}
	writeData(w, 200, resp)
}

// ---- sample reads ----

func canViewSample(s *sessionInfo, sampleID string) bool {
	if s.activeRole == "dispatcher" || s.activeRole == "administrator" {
		return true
	}
	if s.activeRole == "requester" {
		var own int
		db.QueryRow(`SELECT count(*) FROM samples sm JOIN requests r ON r.id=sm.request_id WHERE sm.id=$1 AND r.requester_id=$2`, sampleID, s.userID).Scan(&own)
		return own > 0
	}
	// workers: involved via assignment or custody
	var n int
	db.QueryRow(`SELECT (SELECT count(*) FROM assignments WHERE sample_id=$1 AND (worker_id=$2 OR offered_to=$2)) + (SELECT count(*) FROM samples WHERE id=$1 AND current_holder_id=$2)`, sampleID, s.userID).Scan(&n)
	return n > 0
}

func handleReadSampleState(w http.ResponseWriter, r *http.Request) {
	s := requireAuth("read_sample_state", false, w, r)
	if s == nil {
		return
	}
	id := r.PathValue("sampleId")
	if !canViewSample(s, id) {
		writeErr(w, 403, "forbidden", "you may not view this sample")
		return
	}
	m := readSampleState(id)
	if m == nil {
		writeErr(w, 404, "not_found", "sample not found")
		return
	}
	writeData(w, 200, m)
}

func handleReadSampleLifecycle(w http.ResponseWriter, r *http.Request) {
	s := requireAuth("read_sample_lifecycle", false, w, r)
