package main

import (
	"database/sql"
	"encoding/json"
	"net/http"
	"time"

	"github.com/lib/pq"
	"golang.org/x/crypto/bcrypt"
)

type roleInput struct {
	Role               string `json:"role"`
	AssignedLocationID string `json:"assignedLocationId"`
}

func parseRoles(raw json.RawMessage) ([]string, *apiErr) {
	var roles []string
	if len(raw) == 0 {
		return roles, nil
	}
	// roles may be array of strings or array of objects {role: "..."}
	var strs []string
	if err := json.Unmarshal(raw, &strs); err == nil {
		for _, r := range strs {
			if !validRoles[r] {
				return nil, errOf(400, "invalid_user", "unknown role: "+r)
			}
		}
		return strs, nil
	}
	var objs []roleInput
	if err := json.Unmarshal(raw, &objs); err != nil {
		return nil, errOf(400, "invalid_user", "roles must be an array of role names")
	}
	for _, o := range objs {
		if !validRoles[o.Role] {
			return nil, errOf(400, "invalid_user", "unknown role: "+o.Role)
		}
		roles = append(roles, o.Role)
	}
	return roles, nil
}

type certInput struct {
	Code      string `json:"code"`
	Active    bool   `json:"active"`
	ExpiresAt string `json:"expiresAt"`
}

func parseCerts(raw json.RawMessage) ([]certInput, *apiErr) {
	out := []certInput{}
	if len(raw) == 0 {
		return out, nil
	}
	if err := json.Unmarshal(raw, &out); err != nil {
		return nil, errOf(400, "invalid_certification", "certifications must be objects with code and active")
	}
	for _, c := range out {
		if c.Code == "" {
			return nil, errOf(400, "invalid_certification", "certification code is required")
		}
		if c.ExpiresAt != "" {
			if _, ok := parseTime(c.ExpiresAt); !ok {
				return nil, errOf(400, "invalid_certification", "certification expiresAt must be RFC3339")
			}
		}
	}
	return out, nil
}

func handleCreateUser(w http.ResponseWriter, r *http.Request) {
	s := requireAuth("create_user", true, w, r)
	if s == nil {
		return
	}
	raw, rawBytes, e := decodeRaw(r)
	if e != nil {
		writeAPIErr(w, e)
		return
	}
	get := func(k string) string {
		var v string
		if rv, ok := raw[k]; ok {
			json.Unmarshal(rv, &v)
		}
		return v
	}
	username := get("username")
	password := get("initialPassword")
	if username == "" || password == "" {
		writeErr(w, 400, "invalid_user", "username and initialPassword are required")
		return
	}
	roles, e2 := parseRoles(raw["roles"])
	if e2 != nil {
		writeAPIErr(w, e2)
		return
	}
	if len(roles) == 0 {
		writeErr(w, 400, "invalid_user", "at least one role is required")
		return
	}
	certs, e3 := parseCerts(raw["certifications"])
	if e3 != nil {
		writeAPIErr(w, e3)
		return
	}
	quals := []string{}
	if rv, ok := raw["qualifications"]; ok {
		json.Unmarshal(rv, &quals)
	}
	active := true
	if rv, ok := raw["active"]; ok {
		json.Unmarshal(rv, &active)
	}
	assignedLoc := get("assignedLocationId")
	var exists bool
	db.QueryRow(`SELECT EXISTS(SELECT 1 FROM users WHERE username=$1)`, username).Scan(&exists)
	if exists {
		writeErr(w, 409, "username_exists", "username already exists")
		return
	}
	hash, _ := bcrypt.GenerateFromPassword([]byte(password), bcrypt.DefaultCost)
	id := newUUID()
	_, err := db.Exec(`INSERT INTO users(id,username,password_hash,email,full_name,phone,active,assigned_location_id) VALUES($1,$2,$3,$4,$5,$6,$7,$8)`,
		id, username, string(hash), get("email"), get("fullName"), get("phone"), active, nullUUID(&assignedLoc))
	if err != nil {
		writeErr(w, 400, "invalid_user", err.Error())
		return
	}
	for _, role := range roles {
		db.Exec(`INSERT INTO user_roles(user_id,role) VALUES($1,$2) ON CONFLICT DO NOTHING`, id, role)
	}
	for _, q := range quals {
		db.Exec(`INSERT INTO user_qualifications(user_id,code) VALUES($1,$2) ON CONFLICT DO NOTHING`, id, q)
	}
	for _, c := range certs {
		var exp *time.Time
		if c.ExpiresAt != "" {
			if t, ok := parseTime(c.ExpiresAt); ok {
				exp = &t
			}
		}
		db.Exec(`INSERT INTO user_certifications(user_id,code,active,expires_at) VALUES($1,$2,$3,$4) ON CONFLICT (user_id,code) DO UPDATE SET active=$3, expires_at=$4`, id, c.Code, c.Active, exp)
	}
	audit(s.userID, s.activeRole, "create_user", "user", id, true, M{"username": username, "roles": roles})
	_ = rawBytes
	m, _ := readUserByID(id)
	writeData(w, 201, m)
}

func handleUpdateUserAccess(w http.ResponseWriter, r *http.Request) {
	s := requireAuth("update_user_access", true, w, r)
	if s == nil {
		return
	}
	raw, _, e := decodeRaw(r)
	if e != nil {
		writeAPIErr(w, e)
		return
	}
	var userID string
	json.Unmarshal(raw["userId"], &userID)
	if userID == "" {
		writeErr(w, 400, "invalid_json", "userId is required")
		return
	}
	var exists bool
	db.QueryRow(`SELECT EXISTS(SELECT 1 FROM users WHERE id=$1)`, userID).Scan(&exists)
	if !exists {
		writeErr(w, 404, "not_found", "user not found")
		return
	}
	roles, e2 := parseRoles(raw["roles"])
	if e2 != nil {
		writeAPIErr(w, e2)
		return
	}
	certs, e3 := parseCerts(raw["certifications"])
	if e3 != nil {
		writeAPIErr(w, e3)
		return
	}
	quals := []string{}
	if rv, ok := raw["qualifications"]; ok {
		json.Unmarshal(rv, &quals)
	}
	active := true
	if rv, ok := raw["active"]; ok {
		json.Unmarshal(rv, &active)
	}
	assignedLoc := ""
	if rv, ok := raw["assignedLocationId"]; ok {
		json.Unmarshal(rv, &assignedLoc)
	}
	db.Exec(`UPDATE users SET active=$1, assigned_location_id=$2 WHERE id=$3`, active, nullUUID(&assignedLoc), userID)
	db.Exec(`DELETE FROM user_roles WHERE user_id=$1`, userID)
	for _, role := range roles {
		db.Exec(`INSERT INTO user_roles(user_id,role) VALUES($1,$2) ON CONFLICT DO NOTHING`, userID, role)
	}
	db.Exec(`DELETE FROM user_qualifications WHERE user_id=$1`, userID)
	for _, q := range quals {
		db.Exec(`INSERT INTO user_qualifications(user_id,code) VALUES($1,$2) ON CONFLICT DO NOTHING`, userID, q)
	}
	db.Exec(`DELETE FROM user_certifications WHERE user_id=$1`, userID)
	for _, c := range certs {
		var exp *time.Time
		if c.ExpiresAt != "" {
			if t, ok := parseTime(c.ExpiresAt); ok {
				exp = &t
			}
		}
