	db.Exec(`UPDATE locations SET name=$1,lat=$2,lng=$3,coverage_km=$4,handling_minutes=$5,fn_collection_point=$6,fn_transfer_point=$7,fn_hub=$8,fn_laboratory=$9 WHERE id=$10`,
