// ---------- capacity ----------

func handleConfigureCapacity(w http.ResponseWriter, r *http.Request) {
	s := requireAuth("configure_capacity", true, w, r)
	if s == nil {
		return
	}
	var req struct {
		ResourceID          string `json:"resourceId"`
		CapacityUnits       int    `json:"capacityUnits"`
		CooledCapacityUnits *int   `json:"cooledCapacityUnits"`
	}
	if e := decodeBody(r, &req); e != nil {
		writeAPIErr(w, e)
		return
	}
	if req.CapacityUnits < 0 || (req.CooledCapacityUnits != nil && *req.CooledCapacityUnits < 0) {
		writeErr(w, 400, "invalid_capacity", "capacity units must be non-negative")
		return
	}
	// resource may be a location or a connection
	var kind string
	var resU, coolResU int
	var locAssigned *string
	err := db.QueryRow(`SELECT reserved_units, cooled_reserved_units FROM locations WHERE id=$1`, req.ResourceID).Scan(&resU, &coolResU)
	if err == nil {
		kind = "locations"
		db.QueryRow(`SELECT assigned_location_id FROM users WHERE id=$1`, s.userID).Scan(&locAssigned)
	} else {
		err = db.QueryRow(`SELECT reserved_units, cooled_reserved_units FROM connections WHERE id=$1`, req.ResourceID).Scan(&resU, &coolResU)
		if err == nil {
			kind = "connections"
		}
	}
	if kind == "" {
		writeErr(w, 404, "not_found", "resource not found")
		return
	}
	if s.activeRole != "administrator" {
		// node handlers / lab team may only configure their assigned location
		if kind != "locations" || locAssigned == nil || *locAssigned != req.ResourceID {
			writeErr(w, 403, "forbidden", "may only configure capacity at your assigned location")
			return
		}
	}
	cool := coolResU
	if req.CooledCapacityUnits != nil {
		cool = *req.CooledCapacityUnits
	} else {
		db.QueryRow(`SELECT cooled_capacity_units FROM `+kind+` WHERE id=$1`, req.ResourceID).Scan(&cool)
	}
	if req.CapacityUnits < resU || cool < coolResU {
		writeErr(w, 409, "capacity_reserved", "cannot set capacity below currently reserved units")
		return
	}
	db.Exec(`UPDATE `+kind+` SET capacity_units=$1, cooled_capacity_units=$2 WHERE id=$3`, req.CapacityUnits, cool, req.ResourceID)
	bumpNetworkRevision()
	recomputeServiceabilitySnapshot()
	audit(s.userID, s.activeRole, "configure_capacity", kind[:len(kind)-1], req.ResourceID, true, M{"capacityUnits": req.CapacityUnits, "cooledCapacityUnits": cool})
	writeData(w, 200, M{"resourceId": req.ResourceID, "capacityUnits": req.CapacityUnits, "cooledCapacityUnits": cool})
}

