	if req.CapacityUnits < 0 {
		writeErr(w, 400, "invalid_capacity", "capacityUnits must be non-negative")
		return
	}
	res, _ := db.Exec(`UPDATE users SET available=$1, capacity_units=$2 WHERE id=$3`, req.Available, req.CapacityUnits, req.WorkerID)
	if n, _ := res.RowsAffected(); n == 0 {
		writeErr(w, 404, "not_found", "worker not found")
		return
	}
	audit(s.userID, s.activeRole, "set_worker_availability", "worker", req.WorkerID, true, M{"available": req.Available})
	if req.Available {
		retryNoWorkerAssignments()
	}
	writeData(w, 200, M{"workerId": req.WorkerID, "available": req.Available, "capacityUnits": req.CapacityUnits})
}

// retryNoWorkerAssignments re-offers assignments that were flagged with a
// no_qualified_worker exception, now that worker availability may have changed.
func retryNoWorkerAssignments() {
	rows, err := db.Query(`SELECT a.id FROM assignments a JOIN samples sm ON sm.id=a.sample_id
		WHERE a.status='exception' AND sm.status='exception' AND sm.exception->>'reason'='no_qualified_worker'`)
	if err != nil {
		return
	}
	var ids []string
	for rows.Next() {
		var id string
		rows.Scan(&id)
		ids = append(ids, id)
	}
	rows.Close()
	for _, id := range ids {
		a := loadAssignment(id)
		if a == nil {
			continue
		}
		db.Exec(`UPDATE assignments SET status='pending', offered_to=NULL, offer_expires_at=NULL WHERE id=$1`, id)
		db.Exec(`UPDATE samples SET status='awaiting_collection', exception=NULL WHERE id=$1 AND status='exception'`, a.SampleID)
		if a2 := loadAssignment(id); a2 != nil {
			offerAssignment(a2)
		}
	}
}


// seed default sample types on first migration
func seedSampleTypes() {
	var n int
	db.QueryRow(`SELECT count(*) FROM sample_types`).Scan(&n)
	if n > 0 {
		return
	}
	defaults := []struct {
		name     string
		qual     string
		cooled   bool
		batching bool
		tmin     float64
		tmax     float64
	}{
		{"Amber", "amber", false, true, 2, 25},
		{"Indigo", "indigo", false, true, 2, 25},
		{"Frost", "frost", true, true, -80, -18},
		{"Pulse", "pulse", false, false, 2, 8},
	}
	for _, d := range defaults {
		db.Exec(`INSERT INTO sample_types(id,name,qualified_collector_required,required_qualification,container_type,temp_min,temp_max,requires_cooled_route,batching_allowed) VALUES($1,$2,TRUE,$3,'standard',$4,$5,$6,$7)`,
			newUUID(), d.name, d.qual, d.tmin, d.tmax, d.cooled, d.batching)
	}
	// Indigo incompatible with Amber and vice versa
	var amberID, indigoID string
	db.QueryRow(`SELECT id FROM sample_types WHERE name='Amber'`).Scan(&amberID)
	db.QueryRow(`SELECT id FROM sample_types WHERE name='Indigo'`).Scan(&indigoID)
	db.Exec(`UPDATE sample_types SET incompatible_sample_types=$1 WHERE id=$2`, pq.Array([]string{indigoID}), amberID)
	db.Exec(`UPDATE sample_types SET incompatible_sample_types=$1 WHERE id=$2`, pq.Array([]string{amberID}), indigoID)
}

var _ = sql.ErrNoRows


func handleListSampleTypes(w http.ResponseWriter, r *http.Request) {
s := requireAuth("list_sample_types", false, w, r)
if s == nil {
return
}
rows, err := db.Query(`SELECT id,name,qualified_collector_required,required_qualification,container_type,temp_min,temp_max,incompatible_sample_types,requires_cooled_route,batching_allowed FROM sample_types ORDER BY name`)
if err != nil {
writeErr(w, 500, "internal", err.Error())
return
}
defer rows.Close()
out := []M{}
for rows.Next() {
var id, name, cont string
var qcr bool
var rq sql.NullString
var tmin, tmax float64
var incompat []string
var cooled, batch bool
rows.Scan(&id, &name, &qcr, &rq, &cont, &tmin, &tmax, pq.Array(&incompat), &cooled, &batch)
out = append(out, M{"sampleTypeId": id, "name": name, "qualifiedCollectorRequired": qcr, "requiredQualification": rq.String, "containerType": cont, "temperatureMinC": tmin, "temperatureMaxC": tmax, "incompatibleSampleTypes": incompat, "requiresCooledRoute": cooled, "batchingAllowed": batch})
}
writeData(w, 200, M{"sampleTypes": out})
}

