		name, coord.Latitude, coord.Longitude, cov, hm, fns["collection_point"], fns["transfer_point"], fns["hub"], fns["laboratory"], id)
	bumpNetworkRevision()
	recomputeServiceabilitySnapshot()
	audit(s.userID, s.activeRole, "update_location", "location", id, true, M{"name": name})
	writeData(w, 201, locationJSON(id))
