		CostUnits      float64 `json:"costUnits"`
		Cooled         bool    `json:"cooled"`
		Active         bool    `json:"active"`
	}
	if e := decodeBody(r, &req); e != nil {
		writeAPIErr(w, e)
		return
	}
	if req.FromLocationID == req.ToLocationID || req.TravelMinutes <= 0 {
		writeErr(w, 400, "invalid_connection", "connection endpoints must differ and travelMinutes must be positive")
		return
	}
	var n int
	db.QueryRow(`SELECT count(*) FROM locations WHERE id IN ($1,$2)`, req.FromLocationID, req.ToLocationID).Scan(&n)
	if n != 2 {
		writeErr(w, 400, "invalid_connection", "both locations must exist")
		return
	}
	id := newUUID()
	db.Exec(`INSERT INTO connections(id,from_location_id,to_location_id,travel_minutes,cost_units,cooled,active) VALUES($1,$2,$3,$4,$5,$6,$7)`,
		id, req.FromLocationID, req.ToLocationID, req.TravelMinutes, req.CostUnits, req.Cooled, req.Active)
