// ---- handoffs ----

func handleInitiateHandoff(w http.ResponseWriter, r *http.Request) {
	s := requireAuth("initiate_handoff", true, w, r)
	if s == nil {
		return
	}
	_, rawBytes, e := decodeRaw(r)
	if e != nil {
		writeAPIErr(w, e)
		return
	}
	var req struct {
		FromAssignmentID string `json:"fromAssignmentId"`
		ToAssignmentID   string `json:"toAssignmentId"`
		IdempotencyKey   string `json:"idempotencyKey"`
	}
	json.Unmarshal(rawBytes, &req)
	respondIdempotent(w, s.userID, "initiate_handoff", req.IdempotencyKey, rawBytes, func() (int, any, *apiErr) {
		from := loadAssignment(req.FromAssignmentID)
		to := loadAssignment(req.ToAssignmentID)
		if from == nil || to == nil {
			return 0, nil, errOf(404, "not_found", "assignment not found")
		}
		if from.SampleID != to.SampleID {
			return 0, nil, errOf(409, "invalid_handoff_state", "assignments must reference the same sample")
		}
		if from.WorkerID == nil || *from.WorkerID != s.userID {
			return 0, nil, errOf(403, "forbidden", "you are not the sender of this handoff")
		}
		if to.Status != "accepted" && to.Status != "in_progress" && to.Status != "offered" {
			return 0, nil, errOf(409, "invalid_handoff_state", "receiving assignment is not ready for handoff")
		}
		if from.Status != "accepted" && from.Status != "in_progress" && from.Status != "completed" {
			return 0, nil, errOf(409, "invalid_handoff_state", "sending assignment is not active")
		}
		var existing string
		err := db.QueryRow(`SELECT id FROM handoffs WHERE from_assignment_id=$1 AND to_assignment_id=$2 AND status='pending'`, from.ID, to.ID).Scan(&existing)
		if err == nil {
			return 201, M{"data": handoffInitiateJSON(existing)}, nil
		}
		receiverID := ""
		if to.WorkerID != nil {
			receiverID = *to.WorkerID
		} else if to.OfferedTo != nil {
			receiverID = *to.OfferedTo
		}
		id := newUUID()
		db.Exec(`INSERT INTO handoffs(id,sample_id,from_assignment_id,to_assignment_id,sender_id,receiver_id,status) VALUES($1,$2,$3,$4,$5,$6,'pending')`,
			id, from.SampleID, from.ID, to.ID, s.userID, receiverID)
		audit(s.userID, s.activeRole, "initiate_handoff", "handoff", id, true, M{"sampleId": from.SampleID})
		emitEvent("handoff_initiated", "handoff", id, "", M{"handoffId": id, "sampleId": from.SampleID})
		return 201, M{"data": handoffInitiateJSON(id)}, nil
	})
}

func handleConfirmHandoff(w http.ResponseWriter, r *http.Request) {
	s := requireAuth("confirm_handoff", true, w, r)
	if s == nil {
		return
	}
	_, rawBytes, e := decodeRaw(r)
	if e != nil {
		writeAPIErr(w, e)
		return
	}
	var req struct {
		HandoffID      string `json:"handoffId"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	json.Unmarshal(rawBytes, &req)
	respondIdempotent(w, s.userID, "confirm_handoff", req.IdempotencyKey, rawBytes, func() (int, any, *apiErr) {
		var sampleID, sender, receiver, status string
		var sc, rc bool
		err := db.QueryRow(`SELECT sample_id,sender_id,receiver_id,status,sender_confirmed,receiver_confirmed FROM handoffs WHERE id=$1`, req.HandoffID).
			Scan(&sampleID, &sender, &receiver, &status, &sc, &rc)
		if err != nil {
			return 0, nil, errOf(404, "not_found", "handoff not found")
		}
		if status == "confirmed" {
			return 201, M{"data": handoffConfirmJSON(req.HandoffID)}, nil
		}
		if s.userID != sender && s.userID != receiver {
			return 0, nil, errOf(403, "forbidden", "you are not a party to this handoff")
		}
		if s.userID == sender {
			db.Exec(`UPDATE handoffs SET sender_confirmed=TRUE WHERE id=$1`, req.HandoffID)
			sc = true
		}
		if s.userID == receiver {
			db.Exec(`UPDATE handoffs SET receiver_confirmed=TRUE WHERE id=$1`, req.HandoffID)
			rc = true
		}
		if sc && rc {
			db.Exec(`UPDATE handoffs SET status='confirmed', confirmed_at=now() WHERE id=$1 AND status='pending'`, req.HandoffID)
			// custody transfer
			db.Exec(`UPDATE samples SET current_holder_id=$1 WHERE id=$2`, receiver, sampleID)
			var fromA, toA string
			db.QueryRow(`SELECT from_assignment_id, to_assignment_id FROM handoffs WHERE id=$1`, req.HandoffID).Scan(&fromA, &toA)
			db.Exec(`UPDATE assignments SET status='completed', completed_at=now() WHERE id=$1 AND status IN ('accepted','in_progress')`, fromA)
			// bind receiver to the receiving assignment if it was only offered
			db.Exec(`UPDATE assignments SET worker_id=$1, status='accepted', accepted_at=now() WHERE id=$2 AND worker_id IS NULL AND status='offered'`, receiver, toA)
			// update sample status based on receiver assignment kind
			ta := loadAssignment(toA)
			if ta != nil {
				switch ta.Kind {
				case "node":
					db.Exec(`UPDATE samples SET status='at_node' WHERE id=$1`, sampleID)
				case "laboratory":
					db.Exec(`UPDATE samples SET status='at_laboratory' WHERE id=$1`, sampleID)
				default:
					db.Exec(`UPDATE samples SET status='in_transit' WHERE id=$1`, sampleID)
				}
				maybeOfferNext(ta.JourneyID)
			}
			audit(s.userID, s.activeRole, "confirm_handoff", "handoff", req.HandoffID, true, M{"sampleId": sampleID, "custodyTransferred": true})
			emitEvent("custody_transferred", "sample", sampleID, "", M{"sampleId": sampleID, "newHolderId": receiver})
		} else {
			audit(s.userID, s.activeRole, "confirm_handoff", "handoff", req.HandoffID, true, M{"sampleId": sampleID, "custodyTransferred": false})
		}
		return 201, M{"data": handoffConfirmJSON(req.HandoffID)}, nil
	})
}

